(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[3]=[{"id": "p3-001", "period": 3, "topic_en": "Sugar Act of 1764", "topic_zh": "1764年《糖税法》", "year": 1764, "year_text": "1764", "who": ["George Grenville"], "who_zh": ["乔治·格伦维尔"], "what_en": "George Grenville won parliamentary approval of the Sugar Act of 1764 to replace the widely ignored Molasses Act of 1733. It set a duty of 3 pence per gallon on French molasses and tightened customs enforcement so the duty could actually be collected.", "what_zh": "格伦维尔推动议会通过1764年《糖税法》，取代形同虚设的1733年《糖蜜法》。新法对法国糖蜜征收每加仑3便士的税，并加强海关执法以确保实征。", "cause_en": "Britain needed new colonial revenue to pay the costs of empire after the Great War for Empire, and Grenville wanted far-reaching imperial reform.", "cause_zh": "大战之后英国需要新的殖民地财源支付帝国开支，格伦维尔主张全面的帝国改革。", "sig_en": "It was the first of Grenville's revenue measures; New England merchants such as John Hancock, who had grown rich smuggling French molasses, protested that it would ruin the distilling industry.", "sig_zh": "这是格伦维尔一系列增税措施的开端；靠走私法国糖蜜发家的波士顿商人（如约翰·汉考克）抗议其将摧毁朗姆酒蒸馏业。", "exp_en": "The Sugar Act was Grenville's first attempt to make the colonies pay for imperial administration after the Great War for Empire, and it drew merchants into colonial protest.", "exp_zh": "《糖税法》是格伦维尔在大战后让殖民地分担帝国开支的首次尝试，把商人阶层推入了抗议阵营。", "page": 155, "topic_es": "Sugar Act de 1764", "what_es": "George Grenville obtuvo la aprobación parlamentaria para la Sugar Act de 1764, que reemplazó la ignorada Molasses Act de 1733. Estableció un impuesto de 3 peniques por galón sobre la melaza francesa y reforzó la aplicación aduanera para que el impuesto pudiera recaudarse efectivamente.", "cause_es": "Britain necesitaba nuevos ingresos coloniales para pagar los costos del imperio después de la Great War for Empire, y Grenville quería una reforma imperial de gran alcance.", "sig_es": "Fue la primera de las medidas fiscales de Grenville; comerciantes de New England como John Hancock, que se habían enriquecido con el contrabando de melaza francesa, protestaron que arruinaría la industria de la destilación.", "exp_es": "La Sugar Act fue el primer intento de Grenville de hacer que las colonias pagaran la administración imperial después de la Great War for Empire, y atrajo a los comerciantes a la protesta colonial.", "who_es": ["George Grenville"]}, {"id": "p3-002", "period": 3, "topic_en": "Stamp Act of 1765", "topic_zh": "1765年《印花税法》", "year": 1765, "year_text": "1765", "who": ["George Grenville"], "who_zh": ["乔治·格伦维尔"], "what_en": "The Stamp Act of 1765 required a tax stamp on all printed items, from college diplomas, court documents, land titles, and contracts to newspapers, almanacs, and playing cards. Grenville hoped it would raise 60,000 pounds a year toward the 385,000-pound annual cost of keeping British troops in America.", "what_zh": "1765年《印花税法》要求所有印刷品（大学文凭、法庭文件、地契、合同、报纸、年鉴、扑克牌）贴印花税票。格伦维尔希望每年筹得6万英镑，以分担英国驻军每年38.5万英镑的开销。", "cause_en": "Keeping British troops in America cost far more than first estimated, and Grenville needed colonial revenue to cover part of it.", "cause_zh": "英国在美驻军费用远超预期，格伦维尔需要殖民地财源分担。", "sig_en": "The act sparked the first great imperial crisis; Parliament repealed it in 1766 after colonial boycotts cut into British exports.", "sig_zh": "该法引发第一次帝国大危机；在殖民地抵制导致英国出口受损后，议会于1766年废除了它。", "why_term": "no taxation without representation", "why_term_q": "殖民者抗税的核心原则（关键词）是 ______。", "exp_en": "The Stamp Act touched nearly every colonist who used paper, provoking the first colony-wide crisis over Parliament's right to tax.", "exp_zh": "《印花税法》触及几乎每个用纸的殖民者，引发了第一次全殖民地范围的议会征税权危机。", "page": 157, "topic_es": "Stamp Act de 1765", "what_es": "La Stamp Act de 1765 exigía un timbre fiscal en todos los artículos impresos, desde diplomas universitarios, documentos judiciales, títulos de propiedad y contratos hasta periódicos, almanaques y naipes. Grenville esperaba recaudar 60.000 libras al año para cubrir parte del costo anual de 385.000 libras de mantener las tropas británicas en América.", "cause_es": "Mantener las tropas británicas en América costaba mucho más de lo estimado inicialmente, y Grenville necesitaba ingresos coloniales para cubrir parte de ese costo.", "sig_es": "La ley provocó la primera gran crisis imperial; el Parlamento la derogó en 1766 después de que los boicots coloniales afectaran las exportaciones británicas.", "exp_es": "La Stamp Act afectaba a casi todos los colonos que usaban papel, provocando la primera crisis general en las colonias sobre el derecho del Parlamento a imponer impuestos.", "why_term_q_es": "El principio de que no hay impuestos sin representación (palabra clave) es ______.", "who_es": ["George Grenville"]}, {"id": "p3-003", "period": 3, "topic_en": "Stamp Act Congress", "topic_zh": "印花税法大会", "year": 1765, "year_text": "October 1765", "who": [], "who_zh": [], "what_en": "Nine colonial assemblies sent delegates to the Stamp Act Congress, which met in New York City in October 1765. It declared that only the colonists' elected representatives could tax them, petitioned for repeal of the Stamp Act, and supported a boycott of British goods.", "what_zh": "1765年10月，九个殖民地议会派出代表在纽约召开印花税法大会。大会宣布只有殖民者自己选举的代表才能向他们征税， 请愿要求废除《印花税法》，并支持抵制英货。", "cause_en": "Moderate delegates wanted compromise, not confrontation, after the Stamp Act threatened American rights and liberties, especially trial by jury.", "cause_zh": "《印花税法》威胁到美国人的权利与自由（尤其是陪审团审判权），温和派代表希望通过请愿妥协而非对抗。", "sig_en": "It was the first intercolonial political gathering, asserting a common constitutional principle that would define the Patriot cause.", "sig_zh": "这是第一次跨殖民地政治集会，确立了后来爱国者事业的共同宪法原则。", "exp_en": "The Stamp Act Congress gave the colonies a united voice and a constitutional argument: taxation required representation.", "exp_zh": "印花税法大会让殖民地发出了统一声音，并确立了宪法论据：征税必须有代表。", "page": 158, "topic_es": "Stamp Act Congress", "what_es": "Nueve asambleas coloniales enviaron delegados al Stamp Act Congress, que se reunió en New York City en octubre de 1765. Declaró que solo los representantes electos de los colonos podían imponerles impuestos, pidió la derogación de la Stamp Act y apoyó un boicot a los productos británicos.", "cause_es": "Los delegados moderados querían un compromiso, no una confrontación, después de que la Stamp Act amenazara los derechos y libertades de los americanos, especialmente el juicio por jurado.", "sig_es": "Fue la primera reunión política intercolonial, que afirmó un principio constitucional común que definiría la causa patriota.", "exp_es": "El Stamp Act Congress dio a las colonias una voz unida y un argumento constitucional: los impuestos requerían representación.", "who_es": [], "img": {"file": "img:f1_2388", "credit": "图源：Henretta《America's History》第8版 p.158"}}, {"id": "p3-004", "period": 3, "topic_en": "Sons of Liberty", "topic_zh": "自由之子", "year": 1765, "year_text": "November 1765", "who": ["Sons of Liberty", "John Hancock", "John Adams"], "who_zh": ["自由之子", "约翰·汉考克", "约翰·亚当斯"], "what_en": "When the Stamp Act went into effect on November 1, 1765, a Boston group calling itself the Sons of Liberty burned an effigy of stamp collector Andrew Oliver and destroyed his warehouse; two weeks later Bostonians attacked Lieutenant Governor Thomas Hutchinson's house. Wealthy merchants and Patriot lawyers such as John Hancock and John Adams encouraged the mobs.", "what_zh": "1765年11月1日《印花税法》生效时，波士顿自称“自由之子”的团体焚烧印花税官安德鲁·奥利弗的模拟像并捣毁其仓库；两周后又袭击副总督托马斯·哈钦森的住宅。约翰·汉考克、约翰·亚当斯等富商和爱国者律师暗中鼓励这些暴民行动。", "cause_en": "Peaceful petitions had not stopped Parliament, so popular opposition took a violent crowd-action form to force stamp collectors to resign.", "cause_zh": "和平请愿未能阻止议会，民众于是采取暴力群众行动，迫使印花税官辞职。", "sig_en": "Crowd actions intimidated royal officials in nearly every colony, making the Stamp Act unenforceable and spreading resistance beyond the port cities.", "sig_zh": "群众行动 恐吓了几乎每个殖民地的王室官员，使《印花税法》无法执行，并把抵抗扩散到港口城市之外。", "exp_en": "The Sons of Liberty turned protest into organized crowd pressure that broke the Stamp Act's enforcement.", "exp_zh": "“自由之子”把抗议变成了有组织的群众施压，瓦解了《印花税法》的执行。", "page": 158, "topic_es": "Hijos de la Libertad", "what_es": "Cuando la Stamp Act entró en vigor el 1 de noviembre de 1765, un grupo de Boston que se autodenominaba Hijos de la Libertad quemó una efigie del recaudador de timbres Andrew Oliver y destruyó su almacén; dos semanas después, los bostonianos atacaron la casa del vicegobernador Thomas Hutchinson. Comerciantes adinerados y abogados patriotas como John Hancock y John Adams alentaron a las multitudes.", "cause_es": "Las peticiones pacíficas no habían detenido al Parlamento, así que la oposición popular adoptó la forma violenta de la acción de las multitudes para obligar a los recaudadores a renunciar.", "sig_es": "Las acciones de las multitudes intimidaron a los funcionarios reales en casi todas las colonias, haciendo que la Stamp Act fuera inaplicable y extendiendo la resistencia más allá de las ciudades portuarias.", "exp_es": "Los Hijos de la Libertad convirtieron la protesta en presión organizada de las multitudes que quebró la aplicación de la Stamp Act.", "who_es": ["Hijos de la Libertad", "John Hancock", "John Adams"], "img": {"file": "img:f1_2388", "credit": "图源：Henretta《America's History》第8版 p.158"}}, {"id": "p3-005", "period": 3, "topic_en": "Declaratory Act of 1766", "topic_zh": "1766年《宣示法案》", "year": 1766, "year_text": "1766", "who": [], "who_zh": [], "what_en": "After Rockingham repealed the Stamp Act and reduced the molasses duty, he pacified imperial hard-liners with the Declaratory Act of 1766, which reaffirmed Parliament's full power to bind the colonies and people of America in all cases whatsoever.", "what_zh": "罗金汉废除《印花税法》并降低糖蜜税后，为安抚帝国强硬派通过了1766年《宣示法案》，重申议会在一切情况下约束美洲殖民地及人民的全部权力。", "cause_en": "Grenville's allies demanded that imperial reform continue even after repeal, insisting Parliament had authority to bind every subject whether or not they could vote.", "cause_zh": "格伦维尔的盟友要求即使废除印花税也要继续帝国改革，坚称议会有权约束一切臣民，无论其有无投票权。", "sig_en": "The act kept the constitutional conflict alive: Parliament claimed absolute authority, which made the next tax crisis inevitable.", "sig_zh": "该法使宪法冲突延续：议会宣称绝对权威，为下一次征税危机埋下伏笔。", "exp_en": "Repeal looked like victory, but the Declaratory Act preserved Parliament's claim to tax America at will.", "exp_zh": "废除看似胜利，但《宣示法案》保留了议会任意向美洲征税的主张。", "page": 160, "src": {"text": "full power and authority to make laws and statutes ... to bind the colonies and people of America ... in all cases whatsoever", "attr": "Declaratory Act of 1766"}, "topic_es": "Declaratory Act de 1766", "what_es": "Después de que Rockingham derogara la Stamp Act y redujera el impuesto sobre la melaza, apaciguó a los partidarios de la línea dura imperial con la Declaratory Act de 1766, que reafirmó el pleno poder del Parlamento para obligar a las colonias y al pueblo de América en todos los casos.", "cause_es": "Los aliados de Grenville exigían que la reforma imperial continuara incluso después de la derogación, insistiendo en que el Parlamento tenía autoridad para obligar a todos los súbditos, pudieran votar o no.", "sig_es": "La ley mantuvo vivo el conflicto constitucional: el Parlamento reclamaba una autoridad absoluta, lo que hizo inevitable la próxima crisis fiscal.", "exp_es": "La derogación parecía una victoria, pero la Declaratory Act preservó la pretensión del Parlamento de imponer impuestos a América a voluntad.", "who_es": [], "img": {"file": "img:f1_2394", "credit": "图源：Henretta《America's History》第8版 p.160"}}, {"id": "p3-006", "period": 3, "topic_en": "Townshend Acts of 1767", "topic_zh": "1767年《汤森法案》", "year": 1767, "year_text": "1767", "who": ["Charles Townshend"], "who_zh": ["查尔斯·汤森"], "what_en": "Chancellor of the exchequer Charles Townshend pushed the Townshend Act of 1767, imposing duties on colonial imports of paper, paint, glass, and tea expected to raise about 40,000 pounds a year. Most revenue was earmarked to pay the salaries of royal governors and judges, and a new board of customs commissioners was created in Boston.", "what_zh": "财政大臣查尔斯·汤森推动1767年《汤森法案》，对殖民地进口的纸、颜料、玻璃和茶叶征税，预计年入约4万英镑。大部分收入用于支付王室总督和法官的薪水，并在波士顿设立新的海关委员会。", "cause_en": "Townshend wanted a new American revenue source and intended, by using parliamentary taxes to finance imperial officials, to undermine American political institutions.", "cause_zh": "汤森想开辟新的美洲财源，并意图用议会税收供养帝国官员，从而削弱美洲政治机构。", "sig_en": "The duties revived the constitutional debate over taxation and provoked a second boycott of British goods.", "sig_zh": "这些关税重燃了征税权的宪法争论，并引发了第二次抵制英货运动。", "exp_en": "Townshend taxed trade instead of paper, but colonists rejected the distinction between external and internal taxes.", "exp_zh": "汤森改征贸易税而非纸张税，但殖民者不接受内外税之分。", "page": 161, "topic_es": "Townshend Acts de 1767", "what_es": "El canciller del tesoro Charles Townshend impulsó la Townshend Act de 1767, que imponía aranceles a las importaciones coloniales de papel, pintura, vidrio y té, con los que se esperaba recaudar unas 40.000 libras al año. La mayor parte de los ingresos se destinó a pagar los salarios de los gobernadores y jueces reales, y se creó una nueva junta de comisionados de aduanas en Boston.", "cause_es": "Townshend quería una nueva fuente de ingresos en América y pretendía, al financiar con impuestos parlamentarios a los funcionarios imperiales, socavar las instituciones políticas americanas.", "sig_es": "Los aranceles reavivaron el debate constitucional sobre los impuestos y provocaron un segundo boicot a los productos británicos.", "exp_es": "Townshend gravó el comercio en lugar del papel, pero los colonos rechazaron la distinción entre impuestos externos e internos.", "who_es": ["Charles Townshend"], "img": {"file": "img:f1_2398", "credit": "图源：Henretta《America's History》第8版 p.161"}}, {"id": "p3-007", "period": 3, "topic_en": "Nonimportation movement and Daughters of Liberty", "topic_zh": "抵制英货运动与自由之女", "year": 1768, "year_text": "1768", "who": ["Daughters of Liberty"], "who_zh": ["自由之女"], "what_en": "In February 1768 the Massachusetts assembly condemned the Townshend Act, and Boston and New York merchants began a new boycott of British goods. American women became crucial to the nonimportation movement, producing large quantities of homespun cloth; newspapers celebrated the exploits of the Daughters of Liberty.", "what_zh": "1768年2月马萨诸塞议会谴责《汤森法案》，波士顿和纽约商人开始新一轮抵制英货。美国妇女成为抵制运动的关键力量，大量生产土布；报纸赞扬“自由之女”的事迹。", "cause_en": "Colonial leaders rejected the legitimacy of Townshend's measures, and ministers and officials promoted domestic manufacture of cloth and other necessities.", "cause_zh": "殖民地领袖不承认汤森措施的合法性，牧师和官员提倡自产布匹等必需品。", "sig_en": "In 1768 the colonies cut imports of British manufactures in half; by 1769 they had a trade surplus with Britain, and hard-hit British merchants petitioned Parliament to repeal the Townshend duties.", "sig_zh": "1768年殖民地将英国制成品进口砍半；到1769年对英出现贸易顺差，受损的英国商人 petition（请愿）议会废除汤森关税。", "exp_en": "Women's household production turned a merchants' boycott into a colony-wide economic weapon.", "exp_zh": "妇女的家庭生产把商人的抵制变成了全殖民地范围的经济武器。", "page": 161, "topic_es": "Movimiento de no importación e Hijas de la Libertad", "what_es": "En febrero de 1768, la asamblea de Massachusetts condenó la Townshend Act, y los comerciantes de Boston y New York comenzaron un nuevo boicot a los productos británicos. Las mujeres americanas se volvieron cruciales para el movimiento de no importación, produciendo grandes cantidades de tela casera; los periódicos celebraban las hazañas de las Hijas de la Libertad.", "cause_es": "Los líderes coloniales rechazaron la legitimidad de las medidas de Townshend, y ministros y funcionarios promovieron la manufactura doméstica de telas y otras necesidades.", "sig_es": "En 1768 las colonias redujeron a la mitad las importaciones de manufacturas británicas; para 1769 tenían un superávit comercial con Britain, y los comerciantes británicos afectados pidieron al Parlamento que derogara los aranceles de Townshend.", "exp_es": "La producción doméstica de las mujeres convirtió un boicot de comerciantes en un arma económica en todas las colonias.", "who_es": ["Hijas de la Libertad"], "img": {"file": "img:f1_2398", "credit": "图源：Henretta《America's History》第8版 p.161"}}, {"id": "p3-008", "period": 3, "topic_en": "Boston Massacre", "topic_zh": "波士顿惨案", "year": 1770, "year_text": "March 5, 1770", "who": ["Paul Revere"], "who_zh": ["保罗·里维尔"], "what_en": "On the night of March 5, 1770, a group of nine British redcoats fired into a crowd and killed five townspeople. A subsequent trial exonerated the soldiers, but silversmith Paul Revere issued an engraving of the confrontation and Patriots labeled the incident The Boston Massacre.", "what_zh": "1770年3月5日晚，九名英国红衫军向人群开火，打死五名市民。随后的审判宣告士兵无罪，但银匠保罗·里维尔发行了冲突的版画，爱国者把这一事件称为“波士顿惨案”。", "cause_en": "British troops stationed in Boston numbered 10 percent of the local population, and their presence wore on the locals after years of tension.", "cause_zh": "驻波士顿英军人数占当地人口一成，多年紧张之后军民关系恶化。", "sig_en": "The shooting confirmed the Radical Whig belief that standing armies were instruments of tyranny, and Revere's engraving became Patriot propaganda.", "sig_zh": "枪击事件印证了激进辉格派“常备军是暴政工具”的信念，里维尔的版画成为爱国者宣传武器。", "exp_en": "Five deaths became a symbol of military occupation, even though a trial cleared the soldiers.", "exp_zh": "尽管审判宣告士兵无罪，五条人命成了军事占领的象征。", "page": 166, "topic_es": "Masacre de Boston", "what_es": "La noche del 5 de marzo de 1770, un grupo de nueve soldados británicos disparó contra una multitud y mató a cinco habitantes. Un juicio posterior exoneró a los soldados, pero el platero Paul Revere publicó un grabado del enfrentamiento y los patriotas calificaron el incidente como la Masacre de Boston.", "cause_es": "Las tropas británicas estacionadas en Boston representaban el 10 por ciento de la población local, y su presencia desgastó a los habitantes después de años de tensión.", "sig_es": "El tiroteo confirmó la creencia whig radical de que los ejércitos permanentes eran instrumentos de tiranía, y el grabado de Revere se convirtió en propaganda patriota.", "exp_es": "Cinco muertes se convirtieron en símbolo de la ocupación militar, aunque un juicio absolvió a los soldados.", "who_es": ["Paul Revere"]}, {"id": "p3-009", "period": 3, "topic_en": "Committees of correspondence", "topic_zh": "通讯委员会", "year": 1772, "year_text": "late 1772", "who": ["Samuel Adams"], "who_zh": ["塞缪尔·亚当斯"], "what_en": "Late in 1772 Samuel Adams persuaded the Boston town meeting to set up a committee of correspondence to state the Rights of the Colonists; soon eighty Massachusetts towns had similar committees. After the burning of the customs vessel Gaspee, the Virginia House of Burgesses and other assemblies set up their own.", "what_zh": "1772年底塞缪尔·亚当斯说服波士顿镇民大会设立通讯委员会，阐明殖民者的权利；不久八十个马萨诸塞城镇纷纷效仿。在海关缉私船“加斯皮号”被焚后，弗吉尼亚议会等也设立了各自的委员会。", "cause_en": "Patriots needed standing committees to communicate with leaders in other colonies whenever new threats to liberty occurred.", "cause_zh": "爱国者需要常设委员会，以便在新的自由威胁出现时与其他殖民地领袖联络。", "sig_en": "By 1774, among the colonies that would declare independence, only Pennsylvania was without one; the committees sprang into action when Parliament passed the Tea Act.", "sig_zh": "到1774年，除宾夕法尼亚外所有后来宣布独立的殖民地都有了通讯委员会；议会通过《茶叶法》时这些委员会立即行动起来。", "exp_en": "The committees created the first permanent intercolonial Patriot network.", "exp_zh": "通讯委员会建立了第一个永久性的跨殖民地爱国者联络网。", "page": 168, "topic_es": "Comités de correspondencia", "what_es": "A finales de 1772, Samuel Adams persuadió a la asamblea municipal de Boston para crear un comité de correspondencia que defendiera los Derechos de los Colonos; pronto ochenta pueblos de Massachusetts tenían comités similares. Después del incendio del barco aduanero Gaspee, la Cámara de Burgueses de Virginia y otras asambleas crearon los suyos.", "cause_es": "Los patriotas necesitaban comités permanentes para comunicarse con líderes de otras colonias cada vez que surgieran nuevas amenazas a la libertad.", "sig_es": "Para 1774, entre las colonias que declararían la independencia, solo Pennsylvania carecía de uno; los comités entraron en acción cuando el Parlamento aprobó la Tea Act.", "exp_es": "Los comités crearon la primera red patriota intercolonial permanente.", "who_es": ["Samuel Adams"]}, {"id": "p3-010", "period": 3, "topic_en": "Tea Act of 1773 and the Boston Tea Party", "topic_zh": "1773年《茶叶法》与波士顿倾茶事件", "year": 1773, "year_text": "December 16, 1773", "who": ["Sons of Liberty", "East India Company"], "who_zh": ["自由之子", "东印度公司"], "what_en": "The Tea Act of May 1773 gave the deeply indebted East India Company a government loan and canceled import duties on tea it exported to the colonies. On December 16, 1773, artisans and laborers disguised as Indians boarded the Dartmouth, the Eleanor, and the Beaver, broke open 342 chests of tea valued at about 10,000 pounds, and threw them into Boston harbor.", "what_zh": "1773年5月《茶叶法》给负债累累的东印度公司政府贷款，并取消其向殖民地出口茶叶的进口税。1773年12月16日，装扮成印第安人的工匠和劳工登上“达特茅斯号”“埃莉诺号”“比弗号”，撬开342箱价值约1万英镑的茶叶倒入波士顿港。", "cause_en": "The company had a huge tea surplus because high duties drove Britons and colonists to drink smuggled Dutch tea; Patriots saw the act as a bribe to make Americans accept the tea tax and a monopoly that cut out American wholesalers.", "cause_zh": "高关税使英美民众都喝走私荷兰茶，公司积压大量茶叶；爱国者认为该法是用廉价茶收买美国人接受茶税，且专卖把美洲批发商排除在外。", "sig_en": "John Adams called it an Epoch in History; George III demanded compulsion, and Parliament answered with the Coercive Acts.", "sig_zh": "约翰·亚当斯称之为历史上的纪元；乔治三世要求强制镇压，议会以《强制法案》回应。", "exp_en": "Cheap tea could not buy colonial consent: the monopoly behind the Tea Act made the tax principle visible again.", "exp_zh": "廉价茶叶买不到殖民者的同意：《茶叶法》背后的专卖让征税原则再次凸显。", "page": 168, "src": {"text": "This destruction of the Tea ... must have so important Consequences, that I cannot but consider it as an Epoch in History.", "attr": "John Adams, diary"}, "topic_es": "Tea Act de 1773 y el Motín del té de Boston", "what_es": "La Tea Act de mayo de 1773 otorgó a la endeudada East India Company un préstamo del gobierno y canceló los aranceles de importación sobre el té que exportaba a las colonias. El 16 de diciembre de 1773, artesanos y trabajadores disfrazados de indios abordaron el Dartmouth, el Eleanor y el Beaver, abrieron 342 cofres de té valorados en unas 10.000 libras y los arrojaron al puerto de Boston.", "cause_es": "La compañía tenía un enorme excedente de té porque los altos aranceles llevaban a británicos y colonos a beber té holandés de contrabando; los patriotas vieron la ley como un soborno para que los americanos aceptaran el impuesto sobre el té y un monopolio que eliminaba a los mayoristas americanos.", "sig_es": "John Adams lo llamó una Época en la Historia; George III exigió coerción, y el Parlamento respondió con las Coercive Acts.", "exp_es": "El té barato no pudo comprar el consentimiento colonial: el monopolio detrás de la Tea Act hizo visible de nuevo el principio del impuesto.", "who_es": ["Hijos de la Libertad", "East India Company"]}, {"id": "p3-011", "period": 3, "topic_en": "Coercive Acts (Intolerable Acts)", "topic_zh": "《强制法案》（不可容忍法案）", "year": 1774, "year_text": "early 1774", "who": ["George III", "Lord North"], "who_zh": ["乔治三世", "诺斯勋爵"], "what_en": "Early in 1774 Parliament passed four Coercive Acts to force Massachusetts to pay for the tea and submit to imperial authority. The Boston Port Bill closed Boston Harbor to shipping; other acts tightened royal control over Massachusetts government.", "what_zh": "1774年初议会通过四项《强制法案》，迫使马萨诸塞赔偿茶叶损失并服从帝国权威。《波士顿港口法案》关闭波士顿港；其他法案加强了王室对马萨诸塞政府的控制。", "cause_en": "The king was outraged by the Tea Party: Concessions have made matters worse, George III declared, and the time has come for compulsion.", "cause_zh": "倾茶事件激怒了国王：乔治三世宣称让步只会让事情更糟，现在是强制的时候了。", "sig_en": "The attempt to isolate and punish Boston backfired; Patriots across the colonies united in opposition and convened the First Continental Congress.", "sig_zh": "孤立惩罚波士顿的企图适得其反；各殖民地爱国者团结反对，并召开了第一届大陆会议。", "exp_en": "Punishing Massachusetts united the colonies instead of dividing them.", "exp_zh": "惩罚马萨诸塞反而使各殖民地团结起来，而非分化瓦解。", "page": 168, "topic_es": "Coercive Acts (Intolerable Acts)", "what_es": "A principios de 1774, el Parlamento aprobó cuatro Coercive Acts para obligar a Massachusetts a pagar por el té y someterse a la autoridad imperial. La Boston Port Bill cerró el puerto de Boston al transporte marítimo; otras leyes reforzaron el control real sobre el gobierno de Massachusetts.", "cause_es": "El rey estaba indignado por el Motín del té: «Las concesiones han empeorado las cosas», declaró George III, «y ha llegado la hora de la coerción».", "sig_es": "El intento de aislar y castigar a Boston fracasó; los patriotas de todas las colonias se unieron en oposición y convocaron el Primer Congreso Continental.", "exp_es": "Castigar a Massachusetts unió a las colonias en lugar de dividirlas.", "who_es": ["George III", "Lord North"]}, {"id": "p3-012", "period": 3, "topic_en": "First Continental Congress and the Continental Association", "topic_zh": "第一届大陆会议与《大陆协会》", "year": 1774, "year_text": "September 1774", "who": ["Joseph Galloway"], "who_zh": ["约瑟夫·加洛韦"], "what_en": "The First Continental Congress gathered in Philadelphia in September 1774. Joseph Galloway's plan for a continent-wide union under the king failed by a single vote; instead the delegates demanded repeal of the Coercive Acts and established the Continental Association to enforce a boycott of British goods through local committees.", "what_zh": "1774年9月第一届大陆会议在费城召开。约瑟夫·加洛韦提出的在国王领导下实现大陆联合的方案以一票之差被否决；代表们要求废除《强制法案》，并成立《大陆协会》，通过地方委员会执行抵制英货。", "cause_en": "The Coercive Acts convinced delegates that only collective colonial action could resist Parliament.", "cause_zh": "《强制法案》使代表们相信只有殖民地集体行动才能抵抗议会。", "sig_en": "The Association built a rural network of enforcement committees, raising the political consciousness of ordinary Americans and preparing the ground for independence.", "sig_zh": "《大陆协会》建立了乡村执行委员会网络，提高了普通美国人的政治意识，为独立铺平道路。", "exp_en": "The Congress turned protest into coordinated intercolonial government.", "exp_zh": "大陆会议把抗议变成了协调一致的跨殖民地治理。", "page": 169, "topic_es": "Primer Congreso Continental y la Asociación Continental", "what_es": "El Primer Congreso Continental se reunió en Philadelphia en septiembre de 1774. El plan de Joseph Galloway para una unión continental bajo el rey fracasó por un solo voto; en su lugar, los delegados exigieron la derogación de las Coercive Acts y establecieron la Asociación Continental para imponer un boicot a los productos británicos mediante comités locales.", "cause_es": "Las Coercive Acts convencieron a los delegados de que solo la acción colonial colectiva podía resistir al Parlamento.", "sig_es": "La Asociación construyó una red rural de comités de aplicación, elevando la conciencia política de los americanos comunes y preparando el terreno para la independencia.", "exp_es": "El Congreso convirtió la protesta en un gobierno intercolonial coordinado.", "who_es": ["Joseph Galloway"], "img": {"file": "img:f1_2421", "credit": "图源：Henretta《America's History》第8版 p.169"}}, {"id": "p3-013", "period": 3, "topic_en": "Battles of Lexington and Concord and the Minutemen", "topic_zh": "列克星敦和康科德之战与民兵", "year": 1775, "year_text": "April 18-19, 1775", "who": ["Paul Revere", "Thomas Gage"], "who_zh": ["保罗·里维尔", "托马斯·盖奇"], "what_en": "The Concord town meeting had raised the Minutemen, ready to stand at a minute's warning. On the night of April 18, 1775, General Gage dispatched 700 soldiers to capture colonial leaders and supplies at Concord, but Paul Revere and other riders warned the towns; at dawn militiamen confronted the British first at Lexington and then at Concord.", "what_zh": "康科德镇民大会组建了“一分钟民兵”，随时待命。1775年4月18日夜，盖奇将军派700士兵前往康科德抓捕殖民地领袖并缴获军火，但保罗·里维尔等骑手发出警报；黎明时分民兵先在列克星敦、后在康科德与英军交火。", "cause_en": "London had declared Massachusetts in open rebellion and ordered Gage to march against the rude rabble after Patriots seized armories and formed a defiant assembly at Salem.", "cause_zh": "爱国者夺取军火库并在塞勒姆另立议会后，伦敦宣布马萨诸塞公开叛乱，命令盖奇镇压“粗野暴民”。", "sig_en": "The skirmishes began the armed conflict; an army of 20,000 militiamen soon besieged the British in Boston, and the Second Continental Congress met in May 1775 to organize for war.", "sig_zh": "这些小规模冲突点燃了武装冲突；两万民兵很快围困波士顿英军，第二届大陆会议于1775年5月召开组织战争。", "exp_en": "Lexington and Concord turned a political crisis into a shooting war.", "exp_zh": "列克星敦和康科德把政治危机变成了真枪实弹的战争。", "page": 175, "topic_es": "Batallas de Lexington y Concord y los minutemen", "what_es": "La asamblea municipal de Concord había creado a los minutemen, listos para actuar ante un aviso de un minuto. La noche del 18 de abril de 1775, el general Gage envió 700 soldados a capturar a los líderes coloniales y los suministros en Concord, pero Paul Revere y otros jinetes advirtieron a los pueblos; al amanecer, los milicianos enfrentaron a los británicos primero en Lexington y luego en Concord.", "cause_es": "London había declarado a Massachusetts en rebelión abierta y ordenó a Gage marchar contra la «chusma grosera» después de que los patriotas tomaran arsenales y formaran una desafiante asamblea en Salem.", "sig_es": "Las escaramuzas iniciaron el conflicto armado; un ejército de 20.000 milicianos pronto sitió a los británicos en Boston, y el Segundo Congreso Continental se reunió en mayo de 1775 para organizar la guerra.", "exp_es": "Lexington y Concord convirtieron una crisis política en una guerra con disparos.", "who_es": ["Paul Revere", "Thomas Gage"], "img": {"file": "img:f1_2442", "credit": "图源：Henretta《America's History》第8版 p.175"}}, {"id": "p3-014", "period": 3, "topic_en": "Common Sense by Thomas Paine", "topic_zh": "托马斯·潘恩《常识》", "year": 1776, "year_text": "January 1776", "who": ["Thomas Paine"], "who_zh": ["托马斯·潘恩"], "what_en": "In January 1776 Thomas Paine published Common Sense, a rousing call for independence and republican government. He assaulted monarchy and hereditary succession, calling George III the hard hearted sullen Pharaoh of England. Within six months it went through twenty-five editions and reached hundreds of thousands of people.", "what_zh": "1776年1月托马斯·潘恩发表《常识》，激情呼吁独立和共和政体。他猛烈抨击君主制和世袭继承，称乔治三世为“铁石心肠、阴郁的英格兰法老”。半年内再版二十五次，读者达数十万。", "cause_en": "Popular sentiment was in flux in early 1776, and a single brief pamphlet in stirring, plain language could tip the balance toward independence.", "cause_zh": "1776年初民意摇摆，一本语言通俗、文笔激昂的小册子足以把天平推向独立一边。", "sig_en": "Paine urged Americans to create independent republican states, and his arguments inspired Patriot conventions to demand a break from Britain, leading to Richard Henry Lee's June 1776 resolution.", "sig_zh": "潘恩敦促美国人建立独立的共和州，其论点激励爱国者会议要求与英国决裂，促成了1776年6月李的独立决议案。", "exp_en": "Common Sense made independence thinkable for ordinary readers.", "exp_zh": "《常识》让普通读者觉得独立是可想、可行的。", "page": 178, "src": {"text": "A government of our own is our natural right, 'tis time to part.", "attr": "Thomas Paine, Common Sense"}, "topic_es": "Common Sense de Thomas Paine", "what_es": "En enero de 1776, Thomas Paine publicó Common Sense, un vibrante llamado a la independencia y al gobierno republicano. Atacó la monarquía y la sucesión hereditaria, llamando a George III «el faraón de Inglaterra de corazón duro y hosco». En seis meses pasó por veinticinco ediciones y llegó a cientos de miles de personas.", "cause_es": "El sentimiento popular estaba en fluctuación a principios de 1776, y un solo panfleto breve en un lenguaje conmovedor y sencillo podía inclinar la balanza hacia la independencia.", "sig_es": "Paine instó a los americanos a crear estados republicanos independientes, y sus argumentos inspiraron a las convenciones patriotas a exigir la ruptura con Britain, lo que llevó a la resolución de Richard Henry Lee en junio de 1776.", "exp_es": "Common Sense hizo que la independencia fuera concebible para los lectores comunes.", "who_es": ["Thomas Paine"], "img": {"file": "img:f1_2456", "credit": "图源：Henretta《America's History》第8版 p.178"}}, {"id": "p3-015", "period": 3, "topic_en": "Declaration of Independence", "topic_zh": "《独立宣言》", "year": 1776, "year_text": "July 4, 1776", "who": ["Thomas Jefferson", "John Adams", "Richard Henry Lee"], "who_zh": ["托马斯·杰斐逊", "约翰·亚当斯", "理查德·亨利·李"], "what_en": "On July 4, 1776, the Continental Congress approved the Declaration of Independence, mainly authored by Thomas Jefferson. It vilified George III as a tyrant unfit to rule a free people and proclaimed self-evident truths: that all men are created equal, with unalienable rights of Life, Liberty, and the pursuit of Happiness, and that governments derive just powers from the consent of the governed.", "what_zh": "1776年7月4日大陆会议通过《独立宣言》，主要起草人是托马斯·杰斐逊。宣言痛斥乔治三世是暴君、不配统治自由人民，并宣布不言自明的真理：人人生而平等，拥有生命、自由和追求幸福的不可剥夺的权利，政府的正当权力来自被统治者的同意。", "cause_en": "Armed conflict, Paine's arguments, and Patriot conventions urging a break left committed Patriots ready to take the fateful step after Loyalists withdrew from Congress.", "cause_zh": "武装冲突、潘恩的论点以及爱国者会议要求决裂的呼声，使留下的坚定爱国者在效忠派退出后准备迈出决定性一步。", "sig_en": "By linking individual liberty, popular sovereignty, and republican government with independence, Jefferson made them the defining political values of the new nation.", "sig_zh": "杰斐逊把个人自由、人民主权和共和政体与独立联系起来，使之成为新国家的标志性政治价值。", "why_term": "popular sovereignty", "why_term_q": "宣言中“一切权力属于选民”的原则（关键词）是 ______。", "exp_en": "The Declaration justified revolution with Enlightenment principles that would define American political identity.", "exp_zh": "《独立宣言》用启蒙原则为革命正名，这些原则定义了美国的政治认同。", "page": 178, "src": {"text": "that all men are created equal; that they possess the unalienable rights of Life, Liberty, and the pursuit of Happiness", "attr": "Thomas Jefferson, Declaration of Independence"}, "topic_es": "Declaration of Independence", "what_es": "El 4 de julio de 1776, el Congreso Continental aprobó la Declaration of Independence, escrita principalmente por Thomas Jefferson. Vilipendiaba a George III como un tirano no apto para gobernar a un pueblo libre y proclamaba verdades evidentes: que todos los hombres son creados iguales, con derechos inalienables a la Vida, la Libertad y la búsqueda de la Felicidad, y que los gobiernos derivan sus justos poderes del consentimiento de los gobernados.", "cause_es": "El conflicto armado, los argumentos de Paine y las convenciones patriotas que instaban a la ruptura dejaron a los patriotas comprometidos listos para dar el paso fatídico después de que los lealistas se retiraran del Congreso.", "sig_es": "Al vincular la libertad individual, la soberanía popular y el gobierno republicano con la independencia, Jefferson los convirtió en los valores políticos definitorios de la nueva nación.", "exp_es": "La Declaración justificó la revolución con principios de la Ilustración que definirían la identidad política estadounidense.", "why_term_q_es": "El principio de que todo el poder reside en los votantes (palabra clave) es ______.", "who_es": ["Thomas Jefferson", "John Adams", "Richard Henry Lee"], "img": {"file": "img:f1_2456", "credit": "图源：Henretta《America's History》第8版 p.178"}}, {"id": "p3-016", "period": 3, "topic_en": "Battle of Saratoga", "topic_zh": "萨拉托加战役", "year": 1777, "year_text": "October 1777", "who": ["Horatio Gates", "John Burgoyne"], "who_zh": ["霍雷肖·盖茨", "约翰·伯戈因"], "what_en": "General John Burgoyne's army of 6,000 British and German troops and 600 Loyalists and Indians stalled near Saratoga, New York. American forces led by General Horatio Gates blocked every avenue of escape, and in October 1777 forced Burgoyne to surrender. The Patriots captured more than 5,000 British troops.", "what_zh": "约翰·伯戈因将军率6000英德联军和600效忠派及印第安人，在纽约萨拉托加附近陷入困境。霍雷肖·盖茨将军的美军封锁了所有退路，1777年10月迫使伯戈因投降。爱国者俘虏了5000多名英军。", "cause_en": "Britain's 1777 campaign aimed to isolate New England, but Burgoyne advanced slowly, lost supplies, and was beaten back at Bennington while Howe marched on Philadelphia instead of supporting him.", "cause_zh": "英国1777年战役意在孤立新英格兰，但伯戈因行动迟缓、补给被断，在本宁顿受挫，而豪却去攻打费城而未支援他。", "sig_en": "The victory was the turning point of the war: it ensured the diplomatic success of American representatives in Paris, who won a military alliance with France in 1778.", "sig_zh": "此胜为战争转折点：它确保了美国驻巴黎代表的外交成功，于1778年赢得与法国的军事同盟。", "exp_en": "Saratoga proved the rebellion could win, and France bet on the Americans.", "exp_zh": "萨拉托加证明叛乱能够获胜，法国于是押注美国人。", "page": 187, "src": {"text": "swarmed around the army like birds of prey", "attr": "English sergeant at Saratoga"}, "topic_es": "Batalla de Saratoga", "what_es": "El ejército del general John Burgoyne, de 6.000 soldados británicos y alemanes y 600 lealistas e indios, se detuvo cerca de Saratoga, New York. Las fuerzas americanas lideradas por el general Horatio Gates bloquearon todas las vías de escape y, en octubre de 1777, obligaron a Burgoyne a rendirse. Los patriotas capturaron más de 5.000 soldados británicos.", "cause_es": "La campaña británica de 1777 tenía como objetivo aislar New England, pero Burgoyne avanzó lentamente, perdió suministros y fue rechazado en Bennington mientras Howe marchaba sobre Philadelphia en lugar de apoyarlo.", "sig_es": "La victoria fue el punto de inflexión de la guerra: aseguró el éxito diplomático de los representantes americanos en Paris, quienes ganaron una alianza militar con France en 1778.", "exp_es": "Saratoga demostró que la rebelión podía ganar, y France apostó por los americanos.", "who_es": ["Horatio Gates", "John Burgoyne"], "img": {"file": "img:f1_2489", "credit": "图源：Henretta《America's History》第8版 p.187"}}, {"id": "p3-017", "period": 3, "topic_en": "Valley Forge", "topic_zh": "福吉谷", "year": 1777, "year_text": "winter of 1777-1778", "who": ["George Washington", "Baron von Steuben"], "who_zh": ["乔治·华盛顿", "施托伊本男爵"], "what_en": "In the winter of 1777, while Howe's army lived comfortably in Philadelphia, Washington's army retreated 20 miles to Valley Forge, where 12,000 soldiers and hundreds of camp followers suffered horribly; more than 200 officers resigned, 1,000 soldiers deserted, and 3,000 died from malnutrition and disease. Baron von Steuben, a former Prussian officer and inspector general, instituted a strict drill system.", "what_zh": "1777年冬，豪的军队在费城舒适过冬，华盛顿的军队则退到20英里外的福吉谷，1.2万士兵和数百随军人员 遭受了巨大苦难；200多名军官辞职，1000名士兵开小差，3000人死于营养不良和疾病。前普鲁士军官、总督察施托伊本男爵推行严格操练制度。", "cause_en": "Depreciated Continental currency, nearby farmers who refused depreciated paper money, and the collapse of Patriot morale left the army starving and freezing.", "cause_zh": "大陆币贬值、附近农民拒收贬值纸币、爱国者士气崩溃，使军队又饿又冻。", "sig_en": "Thanks to von Steuben, the smaller army that emerged from Valley Forge in spring 1778 was a much tougher and better-disciplined force.", "sig_zh": "多亏施托伊本，1778年春走出福吉谷的虽是人数更少的军队，却坚韧守纪得多。", "exp_en": "Valley Forge was the Continental army's darkest hour and its making as a professional force.", "exp_zh": "福吉谷是大陆军最黑暗的时刻，也是其蜕变为职业化军队的起点。", "page": 189, "src": {"text": "Poor food — hard lodging — cold weather — fatigue — nasty clothes — nasty cookery.... Why are we sent here to starve and freeze?", "attr": "surgeon at Valley Forge, diary"}, "topic_es": "Valley Forge", "what_es": "En el invierno de 1777, mientras el ejército de Howe vivía cómodamente en Philadelphia, el ejército de Washington se retiró 20 millas a Valley Forge, donde 12.000 soldados y cientos de seguidores del campamento sufrieron horriblemente; más de 200 oficiales renunciaron, 1.000 soldados desertaron y 3.000 murieron de desnutrición y enfermedad. El barón von Steuben, ex oficial prusiano e inspector general, instituyó un estricto sistema de instrucción.", "cause_es": "La depreciada moneda continental, los agricultores cercanos que rechazaban el depreciado papel moneda y el colapso de la moral patriota dejaron al ejército hambriento y helado.", "sig_es": "Gracias a von Steuben, el ejército más pequeño que salió de Valley Forge en la primavera de 1778 era una fuerza mucho más dura y mejor disciplinada.", "exp_es": "Valley Forge fue la hora más oscura del ejército continental y su forja como fuerza profesional.", "who_es": ["George Washington", "Baron von Steuben"], "img": {"file": "img:f1_2495", "credit": "图源：Henretta《America's History》第8版 p.189"}}, {"id": "p3-018", "period": 3, "topic_en": "Philipsburg Proclamation", "topic_zh": "菲利普斯堡宣言", "year": 1779, "year_text": "1779", "who": ["Henry Clinton"], "who_zh": ["亨利·克林顿"], "what_en": "In 1779 the Philipsburg Proclamation declared that any slave who deserted a rebel master would receive protection, freedom, and land from Great Britain. Together with Dunmore's 1775 proclamation, it led some 30,000 African Americans to take refuge behind British lines.", "what_zh": "1779年《菲利普斯堡宣言》宣布，任何逃离叛乱主人的奴隶都将得到英国的保护、自由和土地。它与邓莫尔1775年的宣言一起，促使约3万非裔美国人投奔英军防线。", "cause_en": "Britain's southern strategy exploited the large enslaved population: Patriots admitted they could raise few recruits because so many whites had to stay home to prevent insurrection among the Negroes.", "cause_zh": "英国的南方战略利用了南方庞大的奴隶人口：爱国者承认，因太多白人须留守防范黑人起义，征兵困难。", "sig_en": "The proclamations made the Revolution a triangular war; Washington relented on his 1777 ban, and by war's end some 5,000 African Americans, slave and free, had fought for the Patriot cause.", "sig_zh": "这些宣言使革命成为“三角战争”；华盛顿放宽了1777年的禁令，到战争结束约5000名黑人（奴隶与自由人）为爱国者事业而战。", "exp_en": "Britain's offer of freedom forced both sides to reckon with slavery as a military issue.", "exp_zh": "英国的自由承诺迫使双方都把奴隶制当作军事问题来对待。", "page": 190, "topic_es": "Philipsburg Proclamation", "what_es": "En 1779, la Philipsburg Proclamation declaró que cualquier esclavo que desertara de un amo rebelde recibiría protección, libertad y tierras de Great Britain. Junto con la proclamación de Dunmore de 1775, llevó a unos 30.000 afroamericanos a refugiarse tras las líneas británicas.", "cause_es": "La estrategia sureña de Britain explotó la gran población esclavizada: los patriotas admitían que podían reclutar pocos soldados porque muchos blancos debían quedarse en casa para evitar insurrecciones entre los negros.", "sig_es": "Las proclamaciones convirtieron la Revolución en una guerra triangular; Washington cedió en su prohibición de 1777, y al final de la guerra unos 5.000 afroamericanos, esclavos y libres, habían luchado por la causa patriota.", "exp_es": "La oferta británica de libertad obligó a ambos bandos a enfrentar la esclavitud como un asunto militar.", "who_es": ["Henry Clinton"]}, {"id": "p3-019", "period": 3, "topic_en": "Battle of Yorktown", "topic_zh": "约克镇战役", "year": 1781, "year_text": "October 1781", "who": ["George Washington", "Charles Cornwallis", "Rochambeau"], "who_zh": ["乔治·华盛顿", "查尔斯·康沃利斯", "罗尚博"], "what_en": "Feigning an assault on New York City, Washington secretly marched General Rochambeau's French army from Rhode Island to Virginia while the French fleet took control of Chesapeake Bay. Cornwallis's 9,500-man army was surrounded, outnumbered 2 to 1 on land and cut off by sea; he surrendered at Yorktown in October 1781.", "what_zh": "华盛顿佯攻纽约，暗中率罗尚博的法军从罗得岛南下弗吉尼亚，同时法国舰队控制了切萨皮克湾。康沃利斯9500人的军队被包围，陆上以一敌二、海上退路断绝，于1781年10月在约克镇投降。", "cause_en": "Attrition in the Carolinas weakened Cornwallis, and France finally sent its powerful West Indian fleet to North America, giving Washington his chance.", "cause_zh": "卡罗来纳的消耗战削弱了康沃利斯，法国终于把强大的西印度舰队派往北美，给了华盛顿机会。", "sig_en": "The Franco-American victory broke the resolve of the British government; Lord North exclaimed Oh God! It is all over! and Britain gave up active prosecution of the war.", "sig_zh": "法美联军的胜利击垮了英国政府的决心；诺斯勋爵惊呼“天啊，全完了！”，英国放弃了在北美大陆继续作战。", "exp_en": "Yorktown ended major fighting and forced Britain to negotiate independence.", "exp_zh": "约克镇结束了大规模战斗，迫使英国谈判承认独立。", "page": 195, "src": {"text": "Oh God! It is all over!", "attr": "Lord North"}, "topic_es": "Batalla de Yorktown", "what_es": "Fingiendo un asalto a la ciudad de New York, Washington marchó en secreto con el ejército francés del general Rochambeau desde Rhode Island hasta Virginia mientras la flota francesa tomaba el control de la bahía de Chesapeake. El ejército de Cornwallis, de 9.500 hombres, quedó rodeado, superado 2 a 1 en tierra y aislado por mar; se rindió en Yorktown en octubre de 1781.", "cause_es": "El desgaste en las Carolinas debilitó a Cornwallis, y France finalmente envió su poderosa flota de las West Indies a Norteamérica, dando a Washington su oportunidad.", "sig_es": "La victoria franco-americana quebró la determinación del gobierno británico; Lord North exclamó «¡Dios mío! ¡Todo ha terminado!» y Britain abandonó la prosecución activa de la guerra.", "exp_es": "Yorktown puso fin a los combates importantes y obligó a Britain a negociar la independencia.", "who_es": ["George Washington", "Charles Cornwallis", "Rochambeau"], "img": {"file": "img:f1_2518", "credit": "图源：Henretta《America's History》第8版 p.195"}}, {"id": "p3-020", "period": 3, "topic_en": "Treaty of Paris of 1783", "topic_zh": "1783年《巴黎条约》", "year": 1783, "year_text": "September 1783", "who": ["Benjamin Franklin", "John Adams", "John Jay"], "who_zh": ["本杰明·富兰克林", "约翰·亚当斯", "约翰·杰伊"], "what_en": "In the Treaty of Paris, signed in September 1783, Great Britain formally recognized American independence and relinquished its claims to lands south of the Great Lakes and east of the Mississippi River. American diplomats Franklin, Adams, and Jay negotiated secretly with the British, prepared to sign a separate peace apart from France.", "what_zh": "1783年9月签署的《巴黎条约》中，英国正式承认美国独立，并放弃对五大湖南、密西西比河以东土地的要求。富兰克林、亚当斯和杰伊撇开法国与英国秘密谈判，准备单独媾和。", "cause_en": "France and Spain stalled the talks hoping to seize a West Indian island or Gibraltar, infuriating the American diplomats, while British ministers feared losing a rich sugar island and wanted peace.", "cause_zh": "法西两国拖延谈判以图夺取西印度岛屿或直布罗陀，激怒了美国外交官；英国大臣担心失去富庶的产糖岛屿，也渴望和平。", "sig_en": "The Americans secured extremely favorable terms: independence plus a vast western domain that doubled the new nation's claimed territory.", "sig_zh": "美国人获得了极为有利的条件：独立，外加把新国家 声称的领土扩大一倍的广袤西部。", "exp_en": "Separate negotiations won America more than its allies would have conceded.", "exp_zh": "单独谈判为美国赢得了盟友不愿让出的更多利益。", "page": 196, "topic_es": "Treaty of Paris de 1783", "what_es": "En el Treaty of Paris, firmado en septiembre de 1783, Great Britain reconoció formalmente la independencia americana y renunció a sus reclamos sobre las tierras al sur de los Great Lakes y al este del Mississippi River. Los diplomáticos americanos Franklin, Adams y Jay negociaron en secreto con los británicos, dispuestos a firmar una paz por separado al margen de France.", "cause_es": "France y Spain estancaron las conversaciones con la esperanza de apoderarse de una isla antillana o Gibraltar, enfureciendo a los diplomáticos americanos, mientras los ministros británicos temían perder una rica isla azucarera y querían la paz.", "sig_es": "Los americanos obtuvieron términos extremadamente favorables: la independencia más un vasto dominio occidental que duplicó el territorio reclamado por la nueva nación.", "exp_es": "Las negociaciones por separado ganaron para América más de lo que sus aliados habrían concedido.", "who_es": ["Benjamin Franklin", "John Adams", "John Jay"]}, {"id": "p3-021", "period": 3, "topic_en": "War finance and the currency tax", "topic_zh": "战争财政与货币税", "year": 1781, "year_text": "1776-1781", "who": ["Robert Morris"], "who_zh": ["罗伯特·莫里斯"], "what_en": "Congress issued some 200 million dollars in paper money between 1776 and 1779, which fell to an exchange rate of 42 to 1 in 1779 and 146 to 1 in 1781. Rampant inflation imposed a hidden currency tax on everyone who accepted the paper currency, and those small levies financed the American military victory. Robert Morris, the chief treasury official, secured loans from France and Holland and sold Continental loan certificates.", "what_zh": "1776至1779年间大陆会议发行了约2亿美元纸币，汇率跌至1779年的42比1、1781年的146比1。恶性通胀对每个接受纸币的人征收了隐形的“货币税”，这些点滴税款支撑了美国的军事胜利。财政总管罗伯特·莫里斯从法荷两国获得贷款并出售大陆公债凭证。", "cause_en": "Congress lacked the authority to impose taxes and the states paid requisitions late or not at all, so paper money was the only available finance.", "cause_zh": "国会无权征税，各州摊款迟交或拒交，纸币成为唯一的财源。", "sig_en": "Ordinary citizens who accepted depreciating bills paid for independence out of their pockets; Morris also chartered the Bank of North America and urged a 5 percent import tax to expand national authority.", "sig_zh": "接受贬值纸币的普通民众自掏腰包买来了独立；莫里斯还创办了北美银行并提议5%的进口税以扩大中央权力。", "exp_en": "Inflation was America's hidden war tax, paid by everyone who handled paper money.", "exp_zh": "通胀是美国隐形的战争税，由每个经手纸币的人承担。", "page": 196, "topic_es": "Finanzas de guerra y el impuesto monetario", "what_es": "El Congreso emitió unos 200 millones de dólares en papel moneda entre 1776 y 1779, que cayó a un tipo de cambio de 42 a 1 en 1779 y de 146 a 1 en 1781. La inflación galopante impuso un oculto impuesto monetario a todos los que aceptaban el papel moneda, y esos pequeños gravámenes financiaron la victoria militar americana. Robert Morris, el principal funcionario del tesoro, obtuvo préstamos de France y Holland y vendió certificados de préstamos continentales.", "cause_es": "El Congreso carecía de autoridad para imponer impuestos y los estados pagaban las requisiciones tarde o nunca, así que el papel moneda era la única financiación disponible.", "sig_es": "Los ciudadanos comunes que aceptaban billetes depreciados pagaron la independencia de sus bolsillos; Morris también fundó el Bank of North America e instó un impuesto de importación del 5 por ciento para expandir la autoridad nacional.", "exp_es": "La inflación fue el impuesto de guerra oculto de América, pagado por todos los que manejaban papel moneda.", "who_es": ["Robert Morris"]}, {"id": "p3-022", "period": 3, "topic_en": "Pennsylvania constitution of 1776", "topic_zh": "1776年宾夕法尼亚宪法", "year": 1776, "year_text": "1776", "who": ["John Adams"], "who_zh": ["约翰·亚当斯"], "what_en": "In 1776 Pennsylvania insurgents abolished property ownership as a qualification for voting, granting all taxpaying men the right to vote and hold office. The constitution created a unicameral legislature with complete power and no governor's veto, mandated elementary education, and protected citizens from imprisonment for debt.", "what_zh": "1776年宾夕法尼亚激进派废除财产资格限制，所有纳税男子均可投票和担任公职。新宪法设立拥有全部权力的一院制议会、无总督否决权，规定普及初等教育，保护公民免于因债务入狱。", "cause_en": "A coalition of Scots-Irish farmers, Philadelphia artisans, and Enlightenment intellectuals ousted the Penn family's proprietary government in a democratic impulse.", "cause_zh": "苏格兰-爱尔兰农民、费城工匠和启蒙知识分子的联盟推翻了潘恩家族业主政府，民主冲动高涨。", "sig_en": "John Adams denounced the unicameral legislature as so democratical that it must produce confusion; his Thoughts on Government (1776) answered with mixed government, a bicameral legislature, and checks on majority rule.", "sig_zh": "约翰·亚当斯痛斥一院制“民主过了头，必生混乱”；他在《政府论》（1776）中以混合政体、两院制和对多数统治的制衡作为回应。", "exp_en": "Pennsylvania tested how democratic a republic could be, frightening even Patriot leaders.", "exp_zh": "宾夕法尼亚试验了共和制能有多民主，连爱国者领袖都感到害怕。", "page": 198, "topic_es": "Constitución de Pennsylvania de 1776", "what_es": "En 1776, los insurgentes de Pennsylvania abolieron la propiedad como requisito para votar, otorgando a todos los hombres contribuyentes el derecho a votar y ocupar cargos. La constitución creó una legislatura unicameral con poder completo y sin veto del gobernador, ordenó la educación primaria y protegió a los ciudadanos contra el encarcelamiento por deudas.", "cause_es": "Una coalición de agricultores escoceses-irlandeses, artesanos de Philadelphia e intelectuales de la Ilustración derrocó al gobierno propietario de la familia Penn en un impulso democrático.", "sig_es": "John Adams denunció la legislatura unicameral como tan democrática que debía producir confusión; su Thoughts on Government (1776) respondió con un gobierno mixto, una legislatura bicameral y frenos al gobierno de la mayoría.", "exp_es": "Pennsylvania puso a prueba cuán democrática podía ser una república, asustando incluso a los líderes patriotas.", "who_es": ["John Adams"]}, {"id": "p3-023", "period": 3, "topic_en": "Articles of Confederation", "topic_zh": "《邦联条例》", "year": 1777, "year_text": "November 1777", "who": [], "who_zh": [], "what_en": "Approved by the Continental Congress in November 1777, the Articles of Confederation provided for a loose union in which each state retains its sovereignty, freedom, and independence. Each state had one vote; important laws needed nine of thirteen states, and amendments required unanimous consent.", "what_zh": "1777年11月大陆会议批准《邦联条例》，规定松散联盟，“各州保留其主权、自由和独立”。每州一票；重大法律需十三州中九州同意，修约需一致同意。", "cause_en": "Patriots embracing independence in 1776 envisioned a central government with limited powers that would not interfere with the states' internal governance.", "cause_zh": "1776年拥抱独立的爱国者设想的是权力有限、不干涉各州内部治理的中央政府。", "sig_en": "The Articles created a weak central government without tax power, whose defects — exposed by war debts and Shays's Rebellion — drove the movement for the Constitution.", "sig_zh": "《邦联条例》建立了无征税权的弱中央政府，其缺陷在战债和谢斯起义中暴露，推动了制宪运动。", "exp_en": "Fear of centralized power produced a government too weak to govern.", "exp_zh": "对集权的恐惧造出了一个弱到无法治理的政府。", "page": 200, "topic_es": "Articles of Confederation", "what_es": "Aprobados por el Congreso Continental en noviembre de 1777, los Articles of Confederation establecían una unión laxa en la que cada estado conservaba su soberanía, libertad e independencia. Cada estado tenía un voto; las leyes importantes requerían nueve de trece estados, y las enmiendas exigían consentimiento unánime.", "cause_es": "Los patriotas que abrazaban la independencia en 1776 imaginaban un gobierno central con poderes limitados que no interfiriera en el gobierno interno de los estados.", "sig_es": "Los artículos crearon un gobierno central débil sin poder fiscal, cuyos defectos —expuestos por las deudas de guerra y la Rebelión de Shays— impulsaron el movimiento por la Constitución.", "exp_es": "El miedo al poder centralizado produjo un gobierno demasiado débil para gobernar.", "who_es": [], "img": {"file": "img:f1_2536", "credit": "图源：Henretta《America's History》第8版 p.200"}}, {"id": "p3-024", "period": 3, "topic_en": "Northwest Ordinance of 1787", "topic_zh": "1787年《西北条例》", "year": 1787, "year_text": "1787", "who": [], "who_zh": [], "what_en": "Between 1784 and 1787 the Confederation Congress issued ordinances organizing the western lands, and banned slavery north of the Ohio River. Congress also created the Southwest and Mississippi Territories from lands ceded by North Carolina and Georgia, where slavery was allowed.", "what_zh": "1784至1787年间邦联国会颁布条例组织西部土地，并禁止俄亥俄河北部实行奴隶制。国会还用北卡罗来纳和佐治亚割让的土地设立西南领地和密西西比领地，允许奴隶制存在。", "cause_en": "More than thirty thousand settlers had already moved to Kentucky and Tennessee, and Congress needed to preserve its authority over the West and raise revenue from land sales.", "cause_zh": "已有三万多移民进入肯塔基和田纳西，国会需要维护对西部的权威并靠售地筹款。", "sig_en": "The Ordinance set the precedent for admitting new states on equal terms and drew the first federal line against slavery's expansion.", "sig_zh": "该条例开创了新州平等加入联邦的先例，并首次由联邦划定限制奴隶制扩张的界线。", "exp_en": "The Confederation's greatest achievement organized the West and limited slavery there.", "exp_zh": "邦联最伟大的成就是组织西部并在那里限制奴隶制。", "page": 201, "topic_es": "Northwest Ordinance de 1787", "what_es": "Entre 1784 y 1787, el Congreso de la Confederación emitió ordenanzas que organizaban las tierras occidentales y prohibió la esclavitud al norte del Ohio River. El Congreso también creó los Territorios del Suroeste y del Mississippi a partir de tierras cedidas por North Carolina y Georgia, donde se permitía la esclavitud.", "cause_es": "Más de treinta mil colonos ya se habían mudado a Kentucky y Tennessee, y el Congreso necesitaba preservar su autoridad sobre el Oeste y recaudar ingresos de la venta de tierras.", "sig_es": "La ordenanza sentó el precedente de admitir nuevos estados en igualdad de términos y trazó la primera línea federal contra la expansión de la esclavitud.", "exp_es": "El mayor logro de la Confederación organizó el Oeste y limitó allí la esclavitud.", "who_es": []}, {"id": "p3-025", "period": 3, "topic_en": "Shays's Rebellion", "topic_zh": "谢斯起义", "year": 1786, "year_text": "1786", "who": ["Daniel Shays", "James Bowdoin"], "who_zh": ["丹尼尔·谢斯", "詹姆斯·鲍登"], "what_en": "Massachusetts raised taxes fivefold to pay wartime debts, payable in hard currency. Cash-strapped farmers closed the courts by force, and the protest grew into a full-scale revolt led by Captain Daniel Shays, a Continental army veteran. Governor James Bowdoin used a privately funded force to disperse Shays's ragtag army.", "what_zh": "马萨诸塞为偿还战债把税收提高五倍，且须用硬通货缴纳。缺现金的农民武力关闭法院，抗议演变为大陆军老兵丹尼尔·谢斯上尉领导的全面起义。州长詹姆斯·鲍登动用私人出资的军队驱散了谢斯的乌合之众。", "cause_en": "Farmers could not pay both taxes and debts in hard money; creditors threatened lawsuits and seizures, and the legislature seemed unresponsive.", "cause_zh": "农民无力同时用硬通货缴税还债；债权人威胁起诉和没收财产，议会又不理不睬。", "sig_en": "Spurred by the rebellion, nationalists in Congress secured a resolution calling for a convention to revise the Articles of Confederation.", "sig_zh": "起义促使国会中的 国家主义者推动决议，召开修订《邦联条例》的会议。", "exp_en": "A debtors' revolt convinced elites that the Confederation was too weak to survive.", "exp_zh": "一场债务人起义让精英相信邦联弱到无法存续。", "page": 204, "src": {"text": "had no Intensions to Destroy the Publick Government", "attr": "Captain Adam Wheeler, Shaysite"}, "topic_es": "Rebelión de Shays", "what_es": "Massachusetts quintuplicó los impuestos para pagar las deudas de guerra, pagaderos en moneda fuerte. Los agricultores sin efectivo cerraron los tribunales por la fuerza, y la protesta creció hasta convertirse en una revuelta en toda regla liderada por el capitán Daniel Shays, veterano del ejército continental. El gobernador James Bowdoin usó una fuerza financiada privadamente para dispersar el desharrapado ejército de Shays.", "cause_es": "Los agricultores no podían pagar impuestos y deudas en moneda fuerte; los acreedores amenazaban con demandas y embargos, y la legislatura parecía no responder.", "sig_es": "Impulsados por la rebelión, los nacionalistas en el Congreso lograron una resolución que pedía una convención para revisar los Articles of Confederation.", "exp_es": "Una revuelta de deudores convenció a las élites de que la Confederación era demasiado débil para sobrevivir.", "who_es": ["Daniel Shays", "James Bowdoin"]}, {"id": "p3-026", "period": 3, "topic_en": "Virginia Plan and New Jersey Plan", "topic_zh": "弗吉尼亚方案与新泽西方案", "year": 1787, "year_text": "May 1787", "who": ["James Madison", "William Paterson", "George Washington"], "who_zh": ["詹姆斯·麦迪逊", "威廉·佩特森", "乔治·华盛顿"], "what_en": "At the Philadelphia Convention in May 1787, fifty-five delegates chose to consider James Madison's Virginia Plan: supremacy of national authority, a government established by the people with laws operating directly on citizens, and representation based on population. Delegates from small states rallied behind William Paterson's New Jersey Plan, which kept one vote per state in a unicameral legislature.", "what_zh": "1787年5月费城会议上，55名代表决定审议麦迪逊的弗吉尼亚方案： 国家权威至上、由人民而非各州建立政府、法律直接作用于公民、按人口分配代表。小州代表则团结在佩特森的新泽西方案周围：保留一院制、每州一票。", "cause_en": "Shays's Rebellion and the Articles' failures convinced nationalists that only a powerful central government could save republican government.", "cause_zh": "谢斯起义和《邦联条例》的失败使国家主义者相信，只有强大的中央政府才能挽救共和政体。", "sig_en": "After a month of debate a bare majority of states agreed to use the Virginia Plan as the basis of discussion, raising the odds of a powerful national government.", "sig_zh": "经过一个月辩论，勉强多数的州同意以弗吉尼亚方案为讨论基础，强大中央政府的可能性大增。", "exp_en": "The two plans framed the convention's central fight: national power versus state equality.", "exp_zh": "两个方案框定了会议的核心之争：国家权力对州平等。", "page": 205, "topic_es": "Virginia Plan y New Jersey Plan", "what_es": "En la Convención de Philadelphia en mayo de 1787, cincuenta y cinco delegados decidieron considerar el Virginia Plan de James Madison: supremacía de la autoridad nacional, un gobierno establecido por el pueblo con leyes que operaran directamente sobre los ciudadanos, y representación basada en la población. Los delegados de los estados pequeños se unieron en torno al New Jersey Plan de William Paterson, que mantenía un voto por estado en una legislatura unicameral.", "cause_es": "La Rebelión de Shays y los fracasos de los artículos convencieron a los nacionalistas de que solo un gobierno central poderoso podía salvar el gobierno republicano.", "sig_es": "Después de un mes de debate, una escasa mayoría de estados acordó usar el Virginia Plan como base de discusión, aumentando las probabilidades de un gobierno nacional poderoso.", "exp_es": "Los dos planes enmarcaron la lucha central de la convención: el poder nacional frente a la igualdad de los estados.", "who_es": ["James Madison", "William Paterson", "George Washington"], "img": {"file": "img:f1_2557", "credit": "图源：Henretta《America's History》第8版 p.205"}}, {"id": "p3-027", "period": 3, "topic_en": "Great Compromise", "topic_zh": "大妥协", "year": 1787, "year_text": "1787", "who": [], "who_zh": [], "what_en": "Connecticut delegates proposed that the national legislature's upper chamber, the Senate, have two members from each state, while seats in the lower chamber, the House of Representatives, be apportioned by population, determined every ten years by a national census. After bitter debate the populous states reluctantly accepted this Great Compromise.", "what_zh": "康涅狄格代表提议：国会上院参议院每州两名议员，下院众议院按人口分配席位，每十年人口普查调整一次。经过激烈辩论，人口大州勉强接受了这一“大妥协”。", "cause_en": "The convention was deadlocked over representation of large and small states after choosing the Virginia Plan as its basis.", "cause_zh": "会议在选定弗吉尼亚方案为基础后，在大小州代表权问题上陷入僵局。", "sig_en": "The compromise saved the convention and created the bicameral Congress that still structures American government.", "sig_zh": "妥协挽救了会议，创造了延续至今的两院制国会结构。", "exp_en": "Splitting representation between states and people broke the deadlock.", "exp_zh": "在州与人民之间分配代表权打破了僵局。", "page": 206, "topic_es": "Gran Compromiso", "what_es": "Los delegados de Connecticut propusieron que la cámara alta de la legislatura nacional, el Senado, tuviera dos miembros por estado, mientras que los escaños de la cámara baja, la Cámara de Representantes, se distribuyeran por población, determinada cada diez años por un censo nacional. Después de un amargo debate, los estados populosos aceptaron a regañadientes este Gran Compromiso.", "cause_es": "La convención estaba estancada sobre la representación de los estados grandes y pequeños después de elegir el Virginia Plan como base.", "sig_es": "El compromiso salvó la convención y creó el Congreso bicameral que aún estructura el gobierno estadounidense.", "exp_es": "Dividir la representación entre los estados y el pueblo rompió el estancamiento.", "who_es": []}, {"id": "p3-028", "period": 3, "topic_en": "Federalist-Antifederalist debate over ratification", "topic_zh": "联邦派与反联邦派的批准之争", "year": 1788, "year_text": "1787-1788", "who": ["George Clinton", "Melancton Smith", "Patrick Henry"], "who_zh": ["乔治·克林顿", "梅兰克顿·史密斯", "帕特里克·亨利"], "what_en": "The convention declared the Constitution would take effect when ratified by conventions in nine of thirteen states. Antifederalists feared state governments would lose power, protested the lack of a bill of rights, and warned the government would be run by wealthy men. Federalists promised a bill of rights; Virginia ratified 89 to 79 and New York 30 to 27.", "what_zh": "制宪会议宣布宪法经十三州中九州的批准会议通过即生效。反联邦派担心州政府失权、抗议缺少权利法案、警告政府将被富人把持。联邦派承诺增补权利法案；弗吉尼亚以89比79、纽约以30比27批准。", "cause_en": "The Constitution created a far stronger national government than the Articles, and its opponents drew on Revolutionary fears of centralized power.", "cause_zh": "宪法建立的中央政府远强于邦联，反对者借用了革命时期对集权的恐惧。", "sig_en": "The Federalists' promise of a bill of rights secured the Constitution's adoption in the essential states and its legitimacy.", "sig_zh": "联邦派关于权利法案的承诺确保了宪法在关键州的通过及其合法性。", "exp_en": "Ratification was a close-run fight won by promising to protect individual rights.", "exp_zh": "批准是一场险胜，靠的是保护个人权利的承诺。", "page": 207, "topic_es": "Debate federalista-antifederalista sobre la ratificación", "what_es": "La convención declaró que la Constitución entraría en vigor cuando fuera ratificada por convenciones en nueve de trece estados. Los antifederalistas temían que los gobiernos estatales perdieran poder, protestaban por la falta de un Bill of Rights y advertían que el gobierno sería dirigido por hombres ricos. Los federalistas prometieron un Bill of Rights; Virginia ratificó 89 a 79 y New York 30 a 27.", "cause_es": "La Constitución creó un gobierno nacional mucho más fuerte que los Artículos, y sus oponentes se basaron en los temores revolucionarios al poder centralizado.", "sig_es": "La promesa federalista de un Bill of Rights aseguró la adopción de la Constitución en los estados esenciales y su legitimidad.", "exp_es": "La ratificación fue una lucha reñida ganada con la promesa de proteger los derechos individuales.", "who_es": ["George Clinton", "Melancton Smith", "Patrick Henry"]}, {"id": "p3-029", "period": 3, "topic_en": "Federalist No. 10", "topic_zh": "《联邦党人文集》第十篇", "year": null, "year_text": "1787-1788 (ratification debate)", "who": ["James Madison"], "who_zh": ["詹姆斯·麦迪逊"], "what_en": "In Federalist No. 10, Madison challenged the view that republics only worked in small polities. He argued factions were sown in the nature of man — a landed interest, a manufacturing interest, a mercantile interest, a moneyed interest — and that a large republic would better protect liberty: Extend the sphere and you take in a greater variety of parties and interests, inhibiting a majority eager to invade the rights of other citizens.", "what_zh": "在《联邦党人文集》第十篇中，麦迪逊反驳了共和制只适用于小国的观点。他认为派系根植于人性——土地利益、制造业利益、商业利益、货币利益——而大共和国更能保护自由：“扩大范围就能容纳更多样化的党派和利益”，抑制急于侵犯他者权利的多数。", "cause_en": "Antifederalists argued a large centralized government would lead to domestic tyranny, citing Montesquieu's theory that republics must be small.", "cause_zh": "反联邦派援引孟德斯鸠的理论，认为大而集权的政府必致国内专制，共和制必须小国寡民。", "sig_en": "Madison turned small-republic theory on its head, making the large republic itself a safeguard of liberty and a core Federalist argument for the Constitution.", "sig_zh": "麦迪逊把小共和国理论倒转过来，使大共和国本身成为自由的保障，这是联邦派支持宪法的核心理据。", "exp_en": "Federalist No. 10 remains the classic defense of a large republic against faction.", "exp_zh": "第十篇至今仍是为大共和国抵御派系的经典辩护。", "page": 210, "src": {"text": "Extend the sphere and you take in a greater variety of parties and interests", "attr": "James Madison, Federalist No. 10"}, "topic_es": "Federalist No. 10", "what_es": "En Federalist No. 10, Madison desafió la idea de que las repúblicas solo funcionaban en comunidades pequeñas. Argumentó que las facciones están sembradas en la naturaleza del hombre —un interés terrateniente, un interés manufacturero, un interés mercantil, un interés monetario— y que una república grande protegería mejor la libertad: «Extiendan la esfera y abarcarán una mayor variedad de partidos e intereses», inhibiendo a una mayoría ansiosa por invadir los derechos de otros ciudadanos.", "cause_es": "Los antifederalistas argumentaban que un gobierno centralizado grande llevaría a la tiranía interna, citando la teoría de Montesquieu de que las repúblicas debían ser pequeñas.", "sig_es": "Madison invirtió la teoría de la república pequeña, haciendo de la república grande en sí misma una salvaguardia de la libertad y un argumento federalista central a favor de la Constitución.", "exp_es": "Federalist No. 10 sigue siendo la defensa clásica de una república grande contra las facciones.", "who_es": ["James Madison"], "img": {"file": "img:f1_2566", "credit": "图源：Henretta《America's History》第8版 p.210"}}, {"id": "p3-030", "period": 3, "topic_en": "Judith Sargent Murray and women's rights", "topic_zh": "朱迪思·萨金特·默里与妇女权利", "year": 1790, "year_text": "1790", "who": ["Judith Sargent Murray", "Mary Wollstonecraft"], "who_zh": ["朱迪思·萨金特·默里", "玛丽·沃斯通克拉夫特"], "what_en": "Judith Sargent Murray was perhaps the most accomplished female essayist of the Revolutionary era. Publishing under various pen names, she advocated economic independence and better educational opportunities for women, publishing On the Equality of the Sexes in the Massachusetts Magazine two years before Mary Wollstonecraft's A Vindication of the Rights of Woman (1792).", "what_zh": "朱迪思·萨金特·默里堪称革命时代最杰出的女性散文家。她用多个笔名发表文章，倡导妇女经济独立和更好的教育机会，在《马萨诸塞杂志》发表《论性别平等》，比沃斯通克拉夫特的《女权辩护》（1792）早两年。", "cause_en": "Revolutionary talk of liberty and equality led some women to apply those principles to their own subordinate status.", "cause_zh": "革命关于自由平等的言论，促使一些妇女把这些原则用到自己从属的地位上。", "sig_en": "Murray's essays made the earliest American case for women's intellectual equality and education, though political rights remained closed to women.", "sig_zh": "默里的文章提出了美国最早的妇女智力平等和教育主张，尽管政治权利仍对妇女关闭。", "exp_en": "Revolutionary ideals inspired the first American feminist voice, even as law kept women subordinate.", "exp_zh": "革命理想催生了美国第一个女权主义声音，尽管法律仍使妇女处于从属地位。", "page": 199, "topic_es": "Judith Sargent Murray y los derechos de las mujeres", "what_es": "Judith Sargent Murray fue quizás la ensayista más consumada de la era revolucionaria. Publicando bajo varios seudónimos, defendió la independencia económica y mejores oportunidades educativas para las mujeres, publicando On the Equality of the Sexes en el Massachusetts Magazine dos años antes de A Vindication of the Rights of Woman (1792) de Mary Wollstonecraft.", "cause_es": "El discurso revolucionario de libertad e igualdad llevó a algunas mujeres a aplicar esos principios a su propia condición subordinada.", "sig_es": "Los ensayos de Murray presentaron el primer caso americano a favor de la igualdad intelectual y la educación de las mujeres, aunque los derechos políticos siguieron cerrados para las mujeres.", "exp_es": "Los ideales revolucionarios inspiraron la primera voz feminista americana, incluso cuando la ley mantenía a las mujeres subordinadas.", "who_es": ["Judith Sargent Murray", "Mary Wollstonecraft"], "img": {"file": "img:f1_2531", "credit": "图源：Henretta《America's History》第8版 p.199"}}, {"id": "p3-031", "period": 3, "topic_en": "Hamilton's financial program", "topic_zh": "汉密尔顿的财政计划", "year": 1790, "year_text": "1790-1791", "who": ["Alexander Hamilton", "James Madison"], "who_zh": ["亚历山大·汉密尔顿", "詹姆斯·麦迪逊"], "what_en": "As treasury secretary, Hamilton outlined a program of national mercantilism in three reports: on public credit (January 1790), on a national bank (December 1790), and on manufactures (1791). He asked Congress to redeem at face value the 55 million dollars in Confederation securities, to assume the states' war debts at a cost of 22 million dollars, and to charter the Bank of the United States, jointly owned by private stockholders and the national government.", "what_zh": "任财政部长期间，汉密尔顿在三份报告中提出国家重商主义计划：关于公共信用（1790年1月）、关于国家银行（1790年12月）、关于制造业（1791年）。他要求国会按面值赎回5500万美元邦联债券，以2200万美元承接各州战债，并特许成立由私人股东和联邦政府合资的合众国银行。", "cause_en": "As an underdeveloped nation, the United States needed good credit to secure loans, and Hamilton wanted to enhance national authority and assist financiers and merchants.", "cause_zh": "作为欠发达国家，美国需要良好信用来获得贷款；汉密尔顿想增强国家权威并扶助金融家和商人。", "sig_en": "The program created a fiscal infrastructure of national debt, tariffs, and a national bank that Federalists left as an enduring legacy, though Madison and Patrick Henry condemned it as favoring a monied interest.", "sig_zh": "该计划建立了国债、关税和国家银行的财政基础，成为联邦派留下的持久遗产，尽管麦迪逊和帕特里克·亨利谴责其偏袒食利阶层。", "exp_en": "Hamilton used public finance to bind wealthy creditors to the new national government.", "exp_zh": "汉密尔顿用公共财政把富裕债权人与新联邦政府绑在一起。", "page": 216, "topic_es": "Programa financiero de Hamilton", "what_es": "Como secretario del tesoro, Hamilton esbozó un programa de mercantilismo nacional en tres informes: sobre el crédito público (enero de 1790), sobre un banco nacional (diciembre de 1790) y sobre las manufacturas (1791). Pidió al Congreso que rescatara a valor nominal los 55 millones de dólares en valores de la Confederación, que asumiera las deudas de guerra de los estados a un costo de 22 millones de dólares y que fundara el Bank of the United States, de propiedad conjunta de accionistas privados y el gobierno nacional.", "cause_es": "Como nación subdesarrollada, Estados Unidos necesitaba buen crédito para obtener préstamos, y Hamilton quería reforzar la autoridad nacional y ayudar a financieros y comerciantes.", "sig_es": "El programa creó una infraestructura fiscal de deuda nacional, aranceles y un banco nacional que los federalistas dejaron como legado perdurable, aunque Madison y Patrick Henry lo condenaron por favorecer a un interés adinerado.", "exp_es": "Hamilton usó las finanzas públicas para vincular a los acreedores adinerados con el nuevo gobierno nacional.", "who_es": ["Alexander Hamilton", "James Madison"]}, {"id": "p3-032", "period": 3, "topic_en": "Proclamation of Neutrality", "topic_zh": "《中立宣言》", "year": 1793, "year_text": "1793", "who": ["George Washington"], "who_zh": ["乔治·华盛顿"], "what_en": "In 1793 President Washington issued a Proclamation of Neutrality, allowing U.S. citizens to trade with all belligerents after the First French Republic went to war against a British-led coalition. As neutral carriers, American ships claimed a right to pass through Britain's naval blockade of French ports, and commercial earnings averaged 20 million dollars annually in the 1790s.", "what_zh": "1793年华盛顿总统发表《中立宣言》，在法兰西第一共和国与英国领导的反法联盟开战后，允许美国公民与所有交战国贸易。作为中立承运人，美国船只声称有权通过英国对法国港口的封锁；1790年代美国商业收入年均2000万美元。", "cause_en": "European war disrupted farming and drove up wheat prices, bringing prosperity to American farmers and merchants who could profit as neutral traders.", "cause_zh": "欧洲战争扰乱农业、推高小麦价格，作为中立贸易商的美国农民和商人获利丰厚。", "sig_en": "Neutrality made America rich but drew it into the Anglo-French conflict, as both Britain and France seized American ships, setting up two decades of diplomatic crises.", "sig_zh": "中立让美国致富，却也把美国拖入英法冲突：两国都扣押美国船只，埋下二十年外交危机的伏笔。", "exp_en": "Neutral trade brought a boom that neither belligerent would leave alone.", "exp_zh": "中立贸易带来繁荣，但交战双方都不肯放过这块肥肉。", "page": 219, "topic_es": "Proclamation of Neutrality", "what_es": "En 1793, el presidente Washington emitió una Proclamation of Neutrality, permitiendo a los ciudadanos estadounidenses comerciar con todos los beligerantes después de que la Primera República Francesa entrara en guerra contra una coalición liderada por los británicos. Como transportistas neutrales, los barcos americanos reclamaron el derecho a pasar por el bloqueo naval británico de los puertos franceses, y las ganancias comerciales promediaron 20 millones de dólares anuales en la década de 1790.", "cause_es": "La guerra europea interrumpió la agricultura e hizo subir los precios del trigo, trayendo prosperidad a los agricultores y comerciantes americanos que podían lucrar como comerciantes neutrales.", "sig_es": "La neutralidad enriqueció a América pero la arrastró al conflicto anglo-francés, ya que tanto Britain como France capturaban barcos americanos, preparando dos décadas de crisis diplomáticas.", "exp_es": "El comercio neutral trajo un auge que ningún beligerante dejaría en paz.", "who_es": ["George Washington"]}, {"id": "p3-033", "period": 3, "topic_en": "Whiskey Rebellion", "topic_zh": "威士忌起义", "year": 1794, "year_text": "1794", "who": ["George Washington", "Alexander Hamilton"], "who_zh": ["乔治·华盛顿", "亚历山大·汉密尔顿"], "what_en": "In 1794 western Pennsylvania farmers mounted the Whiskey Rebellion to protest Hamilton's excise tax on spirits, which had cut demand for the corn whiskey they distilled and bartered for eastern manufactures. Like the Sons of Liberty and the Shaysites, they assailed tax collectors; protesters waved banners proclaiming the French slogan Liberty, Equality, Fraternity!", "what_zh": "1794年宾夕法尼亚西部农民发动威士忌起义，抗议汉密尔顿的烈酒消费税——该税打击了他们蒸馏并以之交换东部制成品的玉米威士忌。与自由之子和谢斯派一样，他们袭击税吏；抗议者挥舞着法国口号“自由、平等、博爱！”的旗帜。", "cause_en": "Hamilton's economic policies taxed frontier farmers to fund the national debt, sending their hard-earned money to a distant government.", "cause_zh": "汉密尔顿的经济政策向边疆农民征税以偿还国债，把他们的血汗钱送往遥远的政府。", "sig_en": "To uphold national authority, President Washington raised a militia force of 12,000 troops and dispersed the rebels, demonstrating that the new federal government could enforce its laws.", "sig_zh": "为维护国家权威，华盛顿总统调集1.2万民兵驱散起义者，证明新联邦政府能够执行法律。", "exp_en": "The rebellion tested whether the Constitution's government could tax and coerce; it could.", "exp_zh": "起义考验了宪法政府能否征税和强制执行；答案是能。", "page": 219, "src": {"text": "Liberty, Equality, Fraternity!", "attr": "Whiskey Rebellion protesters' banner"}, "topic_es": "Rebelión del Whisky", "what_es": "En 1794, los agricultores del oeste de Pennsylvania montaron la Rebelión del Whisky para protestar contra el impuesto de Hamilton sobre los licores, que había reducido la demanda del whisky de maíz que destilaban e intercambiaban por manufacturas del este. Como los Hijos de la Libertad y los shaysitas, atacaron a los recaudadores de impuestos; ¡los manifestantes ondeaban pancartas que proclamaban el lema francés «Libertad, Igualdad, Fraternidad!».", "cause_es": "Las políticas económicas de Hamilton gravaban a los agricultores de la frontera para financiar la deuda nacional, enviando su dinero ganado con esfuerzo a un gobierno distante.", "sig_es": "Para defender la autoridad nacional, el presidente Washington reunió una fuerza de milicia de 12.000 soldados y dispersó a los rebeldes, demostrando que el nuevo gobierno federal podía hacer cumplir sus leyes.", "exp_es": "La rebelión puso a prueba si el gobierno de la Constitución podía imponer impuestos y coaccionar; podía.", "who_es": ["George Washington", "Alexander Hamilton"]}, {"id": "p3-034", "period": 3, "topic_en": "Jay's Treaty", "topic_zh": "《杰伊条约》", "year": 1795, "year_text": "1794-1795", "who": ["John Jay"], "who_zh": ["约翰·杰伊"], "what_en": "Jay's Treaty allowed Americans to submit claims for illegal British seizures of ships and required Britain to remove its troops and Indian agents from the Northwest Territory. Despite Republican charges that it was too conciliatory, the Senate ratified it in 1795, but only by the two-thirds majority required by the Constitution.", "what_zh": "《杰伊条约》允许美国人就英国非法扣船提出索赔，并要求英国从西北领地撤走军队和印第安事务代理人。尽管共和派指责其过于妥协，参议院仍于1795年以宪法规定的三分之二多数批准。", "cause_en": "Beginning in late 1793 the British navy seized 250 American ships, and Britain kept troops and agents in the Northwest Territory, intensifying pressure for a settlement.", "cause_zh": "1793年底起英国海军扣押250艘美国船只，且在西北领地保留军队和代理人，解决争端的压力剧增。", "sig_en": "As long as the Federalists were in power, the United States would have a pro-British foreign policy, deepening the partisan divide.", "sig_zh": "只要联邦派掌权，美国就将实行亲英外交政策，党派分歧进一步加深。", "exp_en": "Jay bought peace with Britain at the cost of Republican outrage.", "exp_zh": "杰伊用共和派的愤怒换来了与英国的和平。", "page": 222, "topic_es": "Jay's Treaty", "what_es": "El Jay's Treaty permitió a los americanos presentar reclamos por las incautaciones británicas ilegales de barcos y exigió que Britain retirara sus tropas y agentes indios del Territorio del Noroeste. A pesar de las acusaciones republicanas de que era demasiado conciliador, el Senado lo ratificó en 1795, pero solo por la mayoría de dos tercios requerida por la Constitución.", "cause_es": "A partir de finales de 1793, la armada británica capturó 250 barcos americanos, y Britain mantuvo tropas y agentes en el Territorio del Noroeste, intensificando la presión por un acuerdo.", "sig_es": "Mientras los federalistas estuvieran en el poder, Estados Unidos tendría una política exterior probritánica, profundizando la división partidista.", "exp_es": "Jay compró la paz con Britain al costo de la indignación republicana.", "who_es": ["John Jay"], "img": {"file": "img:f1_2595", "credit": "图源：Henretta《America's History》第8版 p.222"}}, {"id": "p3-035", "period": 3, "topic_en": "Haitian Revolution", "topic_zh": "海地革命", "year": 1791, "year_text": "1791", "who": ["Toussaint L'Ouverture"], "who_zh": ["杜桑·卢维杜尔"], "what_en": "The French plantation colony of Saint-Domingue erupted in a massive slave uprising in 1791 aimed at abolishing slavery. After years of civil war and Spanish and British invasions, black Haitians led by Toussaint L'Ouverture, himself a former slave, fought for freedom; by 1802 the French invasion was faltering in the face of disease and determined black resistance.", "what_zh": "法国种植园殖民地圣多明各于1791年爆发大规模奴隶起义，目标是废除奴隶制。经历多年内战和西班牙、英国入侵后，在前奴隶杜桑·卢维杜尔领导下的黑人海地人为自由而战；到1802年，法国远征军在疾病和黑人顽强抵抗面前节节败退。", "cause_en": "The French Revolution intensified conflict between planters and free blacks in a colony where a small planter elite dominated half a million slaves.", "cause_zh": "法国大革命激化了种植园主与自由黑人之间的冲突，而该殖民地是少数种植园精英统治五十万奴隶的社会。", "sig_en": "The Haitian revolt was a triumph of liberty over slavery; its defeat of France helped push Napoleon to sell Louisiana to the United States in 1803.", "sig_zh": "海地起义是自由战胜奴隶制的胜利；它对法国的打击促使拿破仑于1803年把路易斯安那卖给美国。", "exp_en": "A slave revolution in the Caribbean redrew the map of North America.", "exp_zh": "加勒比的一场奴隶革命重绘了北美地图。", "page": 222, "topic_es": "Revolución haitiana", "what_es": "La colonia francesa de plantación de Saint-Domingue estalló en 1791 en una masiva sublevación de esclavos con el objetivo de abolir la esclavitud. Después de años de guerra civil e invasiones españolas y británicas, los haitianos negros liderados por Toussaint L'Ouverture, él mismo un ex esclavo, lucharon por la libertad; para 1802 la invasión francesa flaqueaba ante la enfermedad y la decidida resistencia negra.", "cause_es": "La Revolución Francesa intensificó el conflicto entre plantadores y negros libres en una colonia donde una pequeña élite de plantadores dominaba a medio millón de esclavos.", "sig_es": "La revuelta haitiana fue un triunfo de la libertad sobre la esclavitud; su derrota de France ayudó a empujar a Napoleon a vender Louisiana a Estados Unidos en 1803.", "exp_es": "Una revolución de esclavos en el Caribe redibujó el mapa de Norteamérica.", "who_es": ["Toussaint L'Ouverture"], "img": {"file": "img:f1_2595", "credit": "图源：Henretta《America's History》第8版 p.222"}}, {"id": "p3-036", "period": 3, "topic_en": "XYZ Affair and the undeclared naval war with France", "topic_zh": "XYZ事件与对法不宣而战的海战", "year": 1798, "year_text": "1798", "who": ["John Adams", "Talleyrand"], "who_zh": ["约翰·亚当斯", "塔列朗"], "what_en": "When French foreign minister Talleyrand solicited a loan and a bribe from American diplomats to stop French seizures of American ships, Adams charged that Talleyrand's agents, whom he dubbed X, Y, and Z, had insulted America's honor. Congress cut off trade with France in 1798 and authorized privateering; the undeclared maritime war resulted in the capture of nearly two hundred French and American merchant vessels.", "what_zh": "法国外长塔列朗向美国外交官索要贷款和贿赂才肯停止扣押美国船只，亚当斯指责塔列朗的代理人（被他称为X、Y、Z）侮辱了美国的荣誉。国会于1798年切断对法贸易并授权私掠；这场不宣而战的海战导致近二百艘法美商船被俘。", "cause_en": "Adams continued Hamilton's pro-British foreign policy and denounced French seizures of American merchant ships.", "cause_zh": "亚当斯延续汉密尔顿的亲英外交政策，谴责法国扣押美国商船。", "sig_en": "The affair inflamed anti-French feeling, boosted the Federalists, and led directly to the Alien and Sedition Acts against Republican critics.", "sig_zh": "该事件激起反法情绪，助长联邦派声势，并直接导致针对共和派批评者的《客籍法》和《惩治煽动法》。", "exp_en": "A bribery scandal turned commercial disputes into a quasi-war.", "exp_zh": "一桩贿赂丑闻把商业纠纷变成了准战争。", "page": 223, "topic_es": "Asunto XYZ y la guerra naval no declarada con France", "what_es": "Cuando el ministro de exteriores francés Talleyrand solicitó un préstamo y un soborno a los diplomáticos americanos para detener las capturas francesas de barcos americanos, Adams acusó a los agentes de Talleyrand, a quienes apodó X, Y y Z, de haber insultado el honor de América. El Congreso cortó el comercio con France en 1798 y autorizó el corso; la guerra marítima no declarada resultó en la captura de casi doscientos buques mercantes franceses y americanos.", "cause_es": "Adams continuó la política exterior probritánica de Hamilton y denunció las capturas francesas de barcos mercantes americanos.", "sig_es": "El asunto inflamó el sentimiento antifrancés, impulsó a los federalistas y llevó directamente a las Alien and Sedition Acts contra los críticos republicanos.", "exp_es": "Un escándalo de soborno convirtió disputas comerciales en una cuasiguerra.", "who_es": ["John Adams", "Talleyrand"], "img": {"file": "img:f1_2597", "credit": "图源：Henretta《America's History》第8版 p.223"}}, {"id": "p3-037", "period": 3, "topic_en": "Alien and Sedition Acts", "topic_zh": "《客籍法》与《惩治煽动法》", "year": 1798, "year_text": "1798", "who": [], "who_zh": [], "what_en": "The Naturalization, Alien, and Sedition Acts of 1798 were passed as Federalists grew hostile to the French Republic and took a harder line against their Republican critics. The Sedition Act criminalized criticism of the federal government.", "what_zh": "1798年《归化法》《客籍法》和《惩治煽动法》在联邦派敌视法兰西共和国、强硬打压共和派批评者之际通过。《惩治煽动法》把批评联邦政府定为犯罪。", "cause_en": "The XYZ Affair and undeclared naval war with France made Federalists see Republican sympathizers with France as disloyal and dangerous.", "cause_zh": "XYZ事件和对法不宣而战使联邦派把同情法国的共和派视为不忠和危险。", "sig_en": "The acts provoked the Virginia and Kentucky Resolutions' states'-rights counterattack and helped elect Jefferson in 1800; Congress later branded them unconstitutional and let them expire in 1801.", "sig_zh": "这些法案引发了弗吉尼亚和肯塔基决议案的州权反击，并助杰斐逊在1800年当选；国会后来宣布其违宪，1801年任其失效。", "exp_en": "Wartime hysteria produced laws that criminalized dissent — and a backlash that ended Federalist rule.", "exp_zh": "战时歇斯底里催生了把异议定罪的法律——以及终结联邦派统治的反弹。", "page": 224, "topic_es": "Alien and Sedition Acts", "what_es": "Las Naturalization, Alien, and Sedition Acts de 1798 se aprobaron cuando los federalistas se volvieron hostiles a la República Francesa y adoptaron una línea más dura contra sus críticos republicanos. La Sedition Act criminalizó la crítica al gobierno federal.", "cause_es": "El Asunto XYZ y la guerra naval no declarada con France hicieron que los federalistas vieran a los simpatizantes republicanos de France como desleales y peligrosos.", "sig_es": "Las leyes provocaron el contraataque de derechos de los estados de las Virginia and Kentucky Resolutions y ayudaron a elegir a Jefferson en 1800; el Congreso las declaró más tarde inconstitucionales y las dejó expirar en 1801.", "exp_es": "La histeria bélica produjo leyes que criminalizaban la disidencia, y una reacción que puso fin al gobierno federalista.", "who_es": []}, {"id": "p3-038", "period": 3, "topic_en": "Virginia and Kentucky Resolutions", "topic_zh": "弗吉尼亚和肯塔基决议案", "year": 1798, "year_text": "1798", "who": ["Thomas Jefferson", "James Madison"], "who_zh": ["托马斯·杰斐逊", "詹姆斯·麦迪逊"], "what_en": "At the urging of Jefferson and Madison, the Kentucky and Virginia legislatures issued resolutions in 1798 declaring the Alien and Sedition Acts to be unauthoritative, void, and of no force. The resolutions set forth a states'-rights interpretation of the Constitution, asserting that the states had a right to judge the legitimacy of national laws.", "what_zh": "在杰斐逊和麦迪逊的推动下，肯塔基和弗吉尼亚议会于1798年发表决议案，宣布《客籍法》和《惩治煽动法》“无权威、无效、没有效力”。决议案提出了宪法的州权解释，主张各州有权判断联邦法律的合法性。", "cause_en": "Republicans believed the Supreme Court could not be trusted to review the acts because most justices were Federalists.", "cause_zh": "共和派认为最高法院多为联邦派法官，不可信其会审查这些法案。", "sig_en": "The conflict set the stage for the election of 1800, and the states'-rights doctrine became a lasting weapon against federal power.", "sig_zh": "这场冲突为1800年大选铺路，州权学说成为对抗联邦权力的持久武器。", "why_term": "states' rights", "why_term_q": "决议案主张各州有权判断联邦法律合法性的学说（关键词）是 ______。", "exp_en": "The resolutions answered federal overreach with the claim that states could judge national laws.", "exp_zh": "决议案以“州可评判联邦法律”的主张回应联邦越权。", "page": 225, "topic_es": "Virginia and Kentucky Resolutions", "what_es": "A instancias de Jefferson y Madison, las legislaturas de Kentucky y Virginia emitieron resoluciones en 1798 declarando que las Alien and Sedition Acts eran «no autoritativas, nulas y sin vigor». Las resoluciones expusieron una interpretación de derechos de los estados de la Constitución, afirmando que los estados tenían derecho a juzgar la legitimidad de las leyes nacionales.", "cause_es": "Los republicanos creían que no se podía confiar en la Corte Suprema para revisar las leyes porque la mayoría de los jueces eran federalistas.", "sig_es": "El conflicto preparó el escenario para la elección de 1800, y la doctrina de los derechos de los estados se convirtió en un arma duradera contra el poder federal.", "exp_es": "Las resoluciones respondieron al exceso federal con la afirmación de que los estados podían juzgar las leyes nacionales.", "why_term_q_es": "La doctrina de que los estados tienen derecho a juzgar la legitimidad de las leyes federales (palabra clave) es ______.", "who_es": ["Thomas Jefferson", "James Madison"], "img": {"file": "img:f1_2604", "credit": "图源：Henretta《America's History》第8版 p.225"}}, {"id": "p3-039", "period": 3, "topic_en": "Treaty of Greenville", "topic_zh": "《格林维尔条约》", "year": 1795, "year_text": "1795", "who": ["Little Turtle", "Anthony Wayne"], "who_zh": ["小海龟", "安东尼·韦恩"], "what_en": "After General Mad Anthony Wayne defeated the Western Confederacy at the Battle of Fallen Timbers in August 1794, the Treaty of Greenville (1795) followed: American negotiators acknowledged Indian ownership of the land, and in return for payments the confederacy led by Miami chief Little Turtle ceded most of Ohio and accepted American sovereignty, placing themselves under the protection of the United States.", "what_zh": "1794年8月“疯子安东尼”韦恩将军在倒木之战中击败西部印第安联盟后，1795年签订《格林维尔条约》：美方承认印第安人对土地的所有权，作为交换，以迈阿密酋长“小海龟”为首的联盟割让俄亥俄大部，接受美国主权，置于美国保护之下。", "cause_en": "The Western Confederacy had crushed American expeditions in 1790 and 1791, and Washington feared an alliance between the confederacy and the British in Canada.", "cause_zh": "西部联盟在1790和1791年击溃美军远征，华盛顿担心其与加拿大英军结盟。", "sig_en": "The treaty opened most of Ohio to American settlement and was followed by Britain's agreement, in Jay's Treaty, to leave the Northwest Territory.", "sig_zh": "条约使俄亥俄大部向美国移民开放，随后英国在《杰伊条约》中同意撤出西北领地。", "exp_en": "Military defeat forced the Ohio tribes into the first great land cession of the republic.", "exp_zh": "军事失败迫使俄亥俄部落接受共和国第一次大割地。", "page": 226, "topic_es": "Treaty of Greenville", "what_es": "Después de que el general Mad Anthony Wayne derrotara a la Confederación Occidental en la Batalla de Fallen Timbers en agosto de 1794, siguió el Treaty of Greenville (1795): los negociadores americanos reconocieron la propiedad india de la tierra y, a cambio de pagos, la confederación liderada por el jefe miami Little Turtle cedió la mayor parte de Ohio y aceptó la soberanía americana, poniéndose bajo la protección de Estados Unidos.", "cause_es": "La Confederación Occidental había aplastado las expediciones americanas en 1790 y 1791, y Washington temía una alianza entre la confederación y los británicos en Canadá.", "sig_es": "El tratado abrió la mayor parte de Ohio al asentamiento americano y fue seguido por el acuerdo de Britain, en el Jay's Treaty, de abandonar el Territorio del Noroeste.", "exp_es": "La derrota militar obligó a las tribus de Ohio a la primera gran cesión de tierras de la república.", "who_es": ["Little Turtle", "Anthony Wayne"]}, {"id": "p3-040", "period": 3, "topic_en": "Marbury v. Madison", "topic_zh": "马伯里诉麦迪逊案", "year": 1803, "year_text": "1803", "who": ["John Marshall", "William Marbury", "James Madison"], "who_zh": ["约翰·马歇尔", "威廉·马伯里", "詹姆斯·麦迪逊"], "what_en": "When Secretary of State James Madison refused to deliver the commission of William Marbury, one of Adams's midnight appointees, Chief Justice John Marshall ruled in Marbury v. Madison (1803) that Marbury had the right to the appointment but the Court could not enforce it. In doing so Marshall voided a section of the Judiciary Act of 1789, asserting the Court's authority to review congressional legislation and interpret the Constitution.", "what_zh": "国务卿麦迪逊拒绝交付亚当斯“午夜任命”的官员威廉·马伯里的委任状，首席大法官约翰·马歇尔在1803年“马伯里诉麦迪逊案”中裁定：马伯里有权获得任命，但法院无权强制执行。马歇尔借此宣布1789年《司法法》部分条款无效，确立了法院审查国会立法、解释宪法的权力。", "cause_en": "The outgoing Federalist Congress had packed the judiciary with midnight appointees, and Jeffersonians challenged Federalist control of the courts.", "cause_zh": "即将卸任的联邦派国会用“午夜任命”塞满司法系统，杰斐逊派挑战联邦派对法院的控制。", "sig_en": "The decision established judicial review: It is emphatically the province and duty of the judicial department to say what the law is, directly challenging the Republican view that state legislatures held that power.", "sig_zh": "该判决确立了司法审查权：“阐明法律是什么，断然是司法部门的职权和责任”，直接挑战了共和派关于州议会拥有该权力的观点。", "exp_en": "Marshall lost the battle over one commission and won the war for the Court's power.", "exp_zh": "马歇尔输掉了一纸委任状的战斗，赢得了法院权力的战争。", "page": 231, "topic_es": "Marbury v. Madison", "what_es": "Cuando el secretario de Estado James Madison se negó a entregar el nombramiento de William Marbury, uno de los nombrados de medianoche de Adams, el presidente de la Corte Suprema John Marshall falló en Marbury v. Madison (1803) que Marbury tenía derecho al nombramiento pero que la Corte no podía hacerlo cumplir. Al hacerlo, Marshall anuló una sección de la Judiciary Act de 1789, afirmando la autoridad de la Corte para revisar la legislación del Congreso e interpretar la Constitución.", "cause_es": "El Congreso federalista saliente había llenado el poder judicial con nombramientos de medianoche, y los jeffersonianos desafiaron el control federalista de los tribunales.", "sig_es": "La decisión estableció la revisión judicial: «Es enfáticamente la provincia y el deber del departamento judicial decir qué es la ley», desafiando directamente la visión republicana de que las legislaturas estatales tenían ese poder.", "exp_es": "Marshall perdió la batalla por un nombramiento y ganó la guerra por el poder de la Corte.", "who_es": ["John Marshall", "William Marbury", "James Madison"]}, {"id": "p3-041", "period": 3, "topic_en": "Louisiana Purchase", "topic_zh": "路易斯安那购地", "year": 1803, "year_text": "1803", "who": ["Thomas Jefferson", "Napoleon", "Robert Livingston", "James Monroe"], "who_zh": ["托马斯·杰斐逊", "拿破仑", "罗伯特·利文斯顿", "詹姆斯·门罗"], "what_en": "Jefferson sent Livingston to Paris to buy New Orleans, but Napoleon, his invasion of Saint-Domingue faltering and a new European war threatening, offered the entire territory of Louisiana for 15 million dollars. Livingston and Monroe concluded the Louisiana Purchase in 1803; Jefferson pragmatically accepted a loose interpretation of the Constitution and used its treaty-making powers to complete the deal.", "what_zh": "杰斐逊派利文斯顿赴巴黎购买新奥尔良，但拿破仑因圣多明各远征受挫、欧洲新战争迫近，索性以1500万美元出售整个路易斯安那。利文斯顿和门罗于1803年达成购地协议；杰斐逊务实地接受了对宪法的宽松解释，动用缔约权完成交易。", "cause_en": "France's failure in Saint-Domingue, the threat of a new European war, and Napoleon's fear of an American invasion of Louisiana made him willing to sell.", "cause_zh": "法国在圣多明各的失败、欧洲新战争的威胁以及拿破仑对美国入侵路易斯安那的担忧，使他愿意出售。", "sig_en": "The purchase doubled the nation's territory; Jefferson hoped the new lands would tempt eastern Indians to move west of the Mississippi.", "sig_zh": "购地使国土翻倍；杰斐逊希望新土地能诱使东部印第安人迁往密西西比河以西。", "exp_en": "Fifteen million dollars bought an empire and forced Jefferson to abandon strict construction.", "exp_zh": "1500万美元买下一个帝国，也迫使杰斐逊放弃了严格释宪立场。", "page": 233, "src": {"text": "We have lived long, but this is the noblest work of our lives.", "attr": "Robert Livingston"}, "topic_es": "Compra de Louisiana", "what_es": "Jefferson envió a Livingston a Paris para comprar New Orleans, pero Napoleon, con su invasión de Saint-Domingue flaqueando y una nueva guerra europea en ciernes, ofreció todo el territorio de Louisiana por 15 millones de dólares. Livingston y Monroe concluyeron la Compra de Louisiana en 1803; Jefferson aceptó pragmáticamente una interpretación flexible de la Constitución y usó sus poderes de celebración de tratados para completar el acuerdo.", "cause_es": "El fracaso de France en Saint-Domingue, la amenaza de una nueva guerra europea y el temor de Napoleon a una invasión americana de Louisiana lo dispusieron a vender.", "sig_es": "La compra duplicó el territorio de la nación; Jefferson esperaba que las nuevas tierras tentaran a los indios del este a mudarse al oeste del Mississippi River.", "exp_es": "Quince millones de dólares compraron un imperio y obligaron a Jefferson a abandonar la construcción estricta.", "who_es": ["Thomas Jefferson", "Napoleon", "Robert Livingston", "James Monroe"]}, {"id": "p3-042", "period": 3, "topic_en": "Embargo Act of 1807", "topic_zh": "1807年《禁运法案》", "year": 1807, "year_text": "1807", "who": ["Thomas Jefferson"], "who_zh": ["托马斯·杰斐逊"], "what_en": "To protect American interests through peaceful coercion, Jefferson pushed the Embargo Act of 1807, prohibiting American ships from leaving their home ports until Britain and France stopped restricting U.S. trade. The embargo cut the American gross national product by 5 percent; exports plunged from 108 million dollars in 1806 to 22 million in 1808.", "what_zh": "为以和平胁迫保护美国利益，杰斐逊推动1807年《禁运法案》，禁止美国船只离港，直到英法停止限制美国贸易。禁运使美国国民生产总值下降5%；出口从1806年的1.08亿美元暴跌至1808年的2200万美元。", "cause_en": "Britain's naval blockade, the seizure of American vessels, impressment of nearly 8,000 sailors between 1802 and 1811, and the 1807 British attack on the U.S. Navy vessel Chesapeake outraged Americans.", "cause_zh": "英国海上封锁、扣押美国船只、1802至1811年间强征近8000名水手，以及1807年英舰袭击美国军舰“切萨皮克号”，激怒了美国人。", "sig_en": "The embargo overestimated British and French reliance on American shipping and underestimated merchants' resistance; it weakened the whole economy and hurt farmers as well as merchants.", "sig_zh": "禁运高估了英法对美国航运的依赖、低估了商人的抵制；它削弱了整个经济，农民和商人都受害。", "exp_en": "Peaceful coercion hurt America more than its targets.", "exp_zh": "和平胁迫伤美国自己比伤目标更重。", "page": 234, "src": {"text": "Never since the battle of Lexington have I seen this country in such a state of exasperation as at present", "attr": "Thomas Jefferson"}, "topic_es": "Embargo Act de 1807", "what_es": "Para proteger los intereses americanos mediante la coerción pacífica, Jefferson impulsó la Embargo Act de 1807, que prohibía a los barcos americanos salir de sus puertos de origen hasta que Britain y France dejaran de restringir el comercio estadounidense. El embargo redujo el producto nacional bruto americano en un 5 por ciento; las exportaciones se desplomaron de 108 millones de dólares en 1806 a 22 millones en 1808.", "cause_es": "El bloqueo naval británico, la captura de buques americanos, la leva forzada de casi 8.000 marineros entre 1802 y 1811 y el ataque británico de 1807 al buque de la Armada estadounidense Chesapeake indignaron a los americanos.", "sig_es": "El embargo sobrestimó la dependencia británica y francesa del transporte marítimo americano y subestimó la resistencia de los comerciantes; debilitó toda la economía y perjudicó tanto a agricultores como a comerciantes.", "exp_es": "La coerción pacífica dañó a América más que a sus objetivos.", "who_es": ["Thomas Jefferson"], "img": {"file": "img:f1_2631", "credit": "图源：Henretta《America's History》第8版 p.234"}}, {"id": "p3-043", "period": 3, "topic_en": "Tecumseh and the Battle of Tippecanoe", "topic_zh": "特库姆塞与蒂珀卡努战役", "year": 1811, "year_text": "November 1811", "who": ["Tecumseh", "William Henry Harrison"], "who_zh": ["特库姆塞", "威廉·亨利·哈里森"], "what_en": "As Tecumseh organized the western Indian peoples for war, William Henry Harrison, governor of the Indiana Territory, decided on a preemptive strike. In November 1811, while Tecumseh was south seeking support from the Chickasaws, Choctaws, and Creeks, Harrison's soldiers and militiamen traded heavy casualties with the confederacy's warriors at the Battle of Tippecanoe and then destroyed the holy village.", "what_zh": "特库姆塞组织西部印第安人备战之际，印第安纳领地总督威廉·亨利·哈里森决定先发制人。1811年11月，趁特库姆塞南下争取奇克索、乔克托和克里克人支持，哈里森的军队在蒂珀卡努战役中与联盟武士激战、双方伤亡惨重，随后捣毁了圣村。", "cause_en": "Britain was assisting Indians in the western territories, and Harrison feared a British-backed Indian confederacy.", "cause_zh": "英国在西部领地援助印第安人，哈里森担心出现英国支持的印第安联盟。", "sig_en": "The battle broke Tecumseh's confederacy and, with British seizures of ships, pushed war hawks Henry Clay and John C. Calhoun to demand war with Britain in 1812.", "sig_zh": "此战击垮了特库姆塞的联盟，并与英国扣船事件一起，把主战派亨利·克莱和约翰·卡尔霍恩推向1812年对英开战。", "exp_en": "Tippecanoe ended the last organized Indian resistance in the Old Northwest before the War of 1812.", "exp_zh": "蒂珀卡努终结了1812年战争前旧西北地区最后一次有组织的印第安抵抗。", "page": 236, "topic_es": "Tecumseh y la Batalla de Tippecanoe", "what_es": "Mientras Tecumseh organizaba a los pueblos indios del oeste para la guerra, William Henry Harrison, gobernador del Territorio de Indiana, decidió un ataque preventivo. En noviembre de 1811, mientras Tecumseh estaba en el sur buscando apoyo de los chickasaws, choctaws y creeks, los soldados y milicianos de Harrison intercambiaron fuertes bajas con los guerreros de la confederación en la Batalla de Tippecanoe y luego destruyeron la aldea sagrada.", "cause_es": "Britain ayudaba a los indios en los territorios occidentales, y Harrison temía una confederación india respaldada por los británicos.", "sig_es": "La batalla quebró la confederación de Tecumseh y, junto con las capturas británicas de barcos, empujó a los halcones de guerra Henry Clay y John C. Calhoun a exigir la guerra con Britain en 1812.", "exp_es": "Tippecanoe puso fin a la última resistencia india organizada en el Viejo Noroeste antes de la Guerra de 1812.", "who_es": ["Tecumseh", "William Henry Harrison"], "img": {"file": "img:f1_2639", "credit": "图源：Henretta《America's History》第8版 p.236"}}, {"id": "p3-044", "period": 3, "topic_en": "War of 1812 and the Treaty of Ghent", "topic_zh": "1812年战争与《根特条约》", "year": 1812, "year_text": "1812-1814", "who": ["James Madison", "Henry Clay", "John C. Calhoun", "John Quincy Adams"], "who_zh": ["詹姆斯·麦迪逊", "亨利·克莱", "约翰·卡德威尔·卡尔霍恩", "约翰·昆西·亚当斯"], "what_en": "In June 1812 a divided Congress declared war on Britain: the Senate voted 19 to 13 and the House 79 to 49. Republican war hawks Henry Clay and John C. Calhoun wanted to seize British Canada and Spanish Florida. The Treaty of Ghent, signed on Christmas Eve 1814, retained the prewar borders of the United States.", "what_zh": "1812年6月分裂的国会对英宣战：参议院19比13、众议院79比49。共和派主战鹰派亨利·克莱和约翰·卡尔霍恩想夺取英属加拿大和西属佛罗里达。1814年圣诞前夜签署的《根特条约》维持了战前边界。", "cause_en": "Britain violated American commercial rights through blockades, seizures, and impressment, and aided western Indians; western and southern war hawks also coveted Canada and Florida.", "cause_zh": "英国以封锁、扣船和强征水手侵犯美国商业权利，还援助西部印第安人；西部和南部主战派也觊觎加拿大和佛罗里达。", "sig_en": "The treaty hardly justified three years of war, but survival of the republic boosted national pride; westward expansion and the war shattered the First Party System.", "sig_zh": "条约几乎配不上三年战争，但共和国的存续提振了民族自豪感；西进与战争击碎了第一政党体系。", "exp_en": "A second war with Britain ended in a draw that felt like a victory.", "exp_zh": "第二次对英战争以平局收场，却被当作胜利来庆祝。", "page": 241, "topic_es": "Guerra de 1812 y el Treaty of Ghent", "what_es": "En junio de 1812, un Congreso dividido declaró la guerra a Britain: el Senado votó 19 a 13 y la Cámara 79 a 49. Los halcones de guerra republicanos Henry Clay y John C. Calhoun querían apoderarse del Canadá británico y la Florida española. El Treaty of Ghent, firmado en la víspera de Navidad de 1814, mantuvo las fronteras de preguerra de Estados Unidos.", "cause_es": "Britain violó los derechos comerciales americanos mediante bloqueos, capturas y levas, y ayudó a los indios occidentales; los halcones de guerra del oeste y del sur también codiciaban Canadá y Florida.", "sig_es": "El tratado apenas justificaba tres años de guerra, pero la supervivencia de la república impulsó el orgullo nacional; la expansión hacia el oeste y la guerra destrozaron el Primer Sistema de Partidos.", "exp_es": "Una segunda guerra con Britain terminó en un empate que se sintió como una victoria.", "who_es": ["James Madison", "Henry Clay", "John C. Calhoun", "John Quincy Adams"]}, {"id": "p3-045", "period": 3, "topic_en": "McCulloch v. Maryland", "topic_zh": "麦卡洛克诉马里兰州案", "year": 1819, "year_text": "1819", "who": ["John Marshall"], "who_zh": ["约翰·马歇尔"], "what_en": "When Congress created the Second Bank of the United States in 1816 with branches competing against state-chartered banks, Maryland imposed a tax on it. In McCulloch v. Maryland (1819), Chief Justice John Marshall's Court asserted the supremacy of national laws over such state taxes.", "what_zh": "1816年国会创办合众国第二银行，其分行与州特许银行竞争，马里兰州遂对其征税。1819年“麦卡洛克诉马里兰州案”中，约翰·马歇尔领导的最高法院宣示了联邦法律对这类州税的至上地位。", "cause_en": "State-chartered banks resented competition from the national bank's branches, and Maryland tried to tax the federal institution out of existence.", "cause_zh": "州特许银行不满国家银行分行的竞争，马里兰试图用征税把联邦机构挤垮。", "sig_en": "The decision was a landmark of Marshall's jurisprudence — judicial authority, supremacy of national laws, and traditional property rights — cementing federal supremacy after the Federalist Party itself had faded.", "sig_zh": "该判决是马歇尔法学的里程碑——司法权威、联邦法律至上、传统财产权——在联邦党本身衰落后 巩固了联邦至上。", "exp_en": "Marshall used a state tax on the Bank to make national supremacy permanent law.", "exp_zh": "马歇尔借马里兰对银行的征税，把联邦至上变成了永久法律。", "page": 241, "topic_es": "McCulloch v. Maryland", "what_es": "Cuando el Congreso creó el Second Bank of the United States en 1816, con sucursales que competían contra bancos con carta estatal, Maryland le impuso un impuesto. En McCulloch v. Maryland (1819), la Corte del presidente John Marshall afirmó la supremacía de las leyes nacionales sobre tales impuestos estatales.", "cause_es": "Los bancos con carta estatal resentían la competencia de las sucursales del banco nacional, y Maryland intentó gravar a la institución federal hasta hacerla desaparecer.", "sig_es": "La decisión fue un hito de la jurisprudencia de Marshall —autoridad judicial, supremacía de las leyes nacionales y derechos de propiedad tradicionales— consolidando la supremacía federal después de que el propio Partido Federalista se hubiera desvanecido.", "exp_es": "Marshall usó un impuesto estatal sobre el Banco para hacer permanente la supremacía nacional.", "who_es": ["John Marshall"]}, {"id": "p3-046", "period": 3, "topic_en": "Adams-Onis Treaty", "topic_zh": "《亚当斯—奥尼斯条约》", "year": 1819, "year_text": "1819", "who": ["John Quincy Adams"], "who_zh": ["约翰·昆西·亚当斯"], "what_en": "In the Adams-Onis Treaty of 1819, Secretary of State John Quincy Adams persuaded Spain to cede the Florida territory to the United States. In return, the American government accepted Spain's claim to Texas and agreed to a compromise on the western boundary of Louisiana. Adams had also negotiated the Rush-Bagot Treaty (1817) and the forty-ninth parallel border with Britain (1818).", "what_zh": "1819年《亚当斯—奥尼斯条约》中，国务卿约翰·昆西·亚当斯说服西班牙把佛罗里达割让给美国。作为交换，美国政府承认西班牙对得克萨斯的要求，并在路易斯安那西界问题上妥协。亚当斯此前还谈成了《拉什—巴戈特条约》（1817）和与英国的北纬49度边界（1818）。", "cause_en": "American expansionists coveted Florida, and Spain, weakened by its Latin American revolutions, could no longer hold it.", "cause_zh": "美国扩张主义者觊觎佛罗里达，而西班牙因拉美革命而衰弱，无力保有。", "sig_en": "The treaty gave the United States Florida and, with the northern boundary settlements, won international acceptance of America's northern and western boundaries.", "sig_zh": "条约使美国获得佛罗里达，并与北部边界 一揽子解决一起，赢得国际社会对美国南北疆界的承认。", "exp_en": "Adams's diplomacy secured the continent's borders without war.", "exp_zh": "亚当斯的外交不战而定了大陆疆界。", "page": 243, "topic_es": "Adams-Onis Treaty", "what_es": "En el Adams-Onis Treaty de 1819, el secretario de Estado John Quincy Adams persuadió a Spain para ceder el territorio de Florida a Estados Unidos. A cambio, el gobierno americano aceptó el reclamo de Spain sobre Texas y acordó un compromiso sobre la frontera occidental de Louisiana. Adams también había negociado el Rush-Bagot Treaty (1817) y la frontera del paralelo cuarenta y nueve con Britain (1818).", "cause_es": "Los expansionistas americanos codiciaban Florida, y Spain, debilitada por sus revoluciones latinoamericanas, ya no podía retenerla.", "sig_es": "El tratado dio Florida a Estados Unidos y, con los acuerdos de la frontera norte, ganó la aceptación internacional de las fronteras norte y oeste estadounidenses.", "exp_es": "La diplomacia de Adams aseguró las fronteras del continente sin guerra.", "who_es": ["John Quincy Adams"], "img": {"file": "img:f1_2657", "credit": "图源：Henretta《America's History》第8版 p.243"}}, {"id": "p3-047", "period": 3, "topic_en": "Monroe Doctrine", "topic_zh": "门罗主义", "year": 1823, "year_text": "1823", "who": ["James Monroe", "John Quincy Adams"], "who_zh": ["詹姆斯·门罗", "约翰·昆西·亚当斯"], "what_en": "At Adams's behest, President Monroe warned Spain and other European powers to keep their hands off the newly independent republics in Latin America: the American continents were not subject for further colonization. In return, Monroe pledged the United States would not interfere in the internal concerns of European nations. Thirty years later the policy became known as the Monroe Doctrine.", "what_zh": "在亚当斯的敦促下，门罗总统警告西班牙等欧洲列强不得染指拉丁美洲新独立的共和国：美洲大陆不再是未来殖民的对象。作为交换，门罗承诺美国不干涉欧洲国家的内部事务。三十年后这一政策被称为“门罗主义”。", "cause_en": "Latin American republics had won independence, and the United States wanted to assert diplomatic leadership in the Western Hemisphere and block European recolonization.", "cause_zh": "拉美共和国纷纷独立，美国想确立在西半球的外交领导地位，阻止欧洲重新殖民。", "sig_en": "The doctrine declared American hemispheric primacy and, with Adams's boundary treaties, completed the diplomatic settlement of the continent.", "sig_zh": "该主义宣告了美国在半球的首要地位，与亚当斯的边界条约一起完成了大陆的外交布局。", "exp_en": "A young republic told Europe to stay out of the Americas — and meant it as policy.", "exp_zh": "一个年轻的共和国告诉欧洲不要插手美洲——并将其定为国策。", "page": 244, "src": {"text": "subject for further colonization", "attr": "James Monroe, 1823 message"}, "topic_es": "Monroe Doctrine", "what_es": "A instancias de Adams, el presidente Monroe advirtió a Spain y otras potencias europeas que mantuvieran sus manos fuera de las repúblicas recién independizadas de América Latina: los continentes americanos no estaban sujetos a más colonización. A cambio, Monroe prometió que Estados Unidos no interferiría en los asuntos internos de las naciones europeas. Treinta años después, la política se conocería como la Monroe Doctrine.", "cause_es": "Las repúblicas latinoamericanas habían ganado la independencia, y Estados Unidos quería afirmar el liderazgo diplomático en el hemisferio occidental y bloquear la recolonización europea.", "sig_es": "La doctrina declaró la primacía hemisférica americana y, con los tratados de límites de Adams, completó el arreglo diplomático del continente.", "exp_es": "Una joven república dijo a Europa que se mantuviera fuera de las Américas, y lo dijo en serio como política.", "who_es": ["James Monroe", "John Quincy Adams"], "img": {"file": "img:f1_2663", "credit": "图源：Henretta《America's History》第8版 p.244"}}, {"id": "p3-048", "period": 3, "topic_en": "Neomercantilism and the Commonwealth System", "topic_zh": "新重商主义与州主导的公益体系", "year": null, "year_text": "after 1800", "who": [], "who_zh": [], "what_en": "After 1800 republican state legislatures embraced a neomercantilist system of government-assisted economic development: they chartered corporations, upheld eminent-domain grants to private transportation companies, and funneled state aid to private businesses whose projects would improve the general welfare — a Commonwealth System. Average per capita income rose more than 1 percent a year, over 30 percent in a generation.", "what_zh": "1800年后共和派州议会奉行新重商主义的政府扶助经济发展：特许公司、支持以征用权授予私营交通公司、把州援助输送给有益公共福利的私营企业——即“公益体系”。人均收入年均增长超1%，一代人增长三成以上。", "cause_en": "Jefferson's embargo of 1807 cut off European goods and credit, pushing states to charter domestic companies: New England chartered two hundred companies and Pennsylvania more than eleven hundred.", "cause_zh": "杰斐逊1807年禁运切断了欧洲商品和信贷，各州转而特许本土公司：新英格兰特许200家，宾夕法尼亚1100多家。", "sig_en": "State mercantilism created a republican political economy that made private property and market exchange compatible with activist government.", "sig_zh": "州重商主义创造了共和政治经济学，使私有财产和市场交换与积极政府相兼容。", "exp_en": "Early American growth was built with public help, not laissez-faire alone.", "exp_zh": "早期美国的增长靠的是政府扶助，而非纯粹的自由放任。", "page": 250, "topic_es": "Neomercantilismo y el Sistema Commonwealth", "what_es": "Después de 1800, las legislaturas estatales republicanas abrazaron un sistema neomercantilista de desarrollo económico asistido por el gobierno: otorgaban cartas corporativas, defendían concesiones de dominio eminente a compañías privadas de transporte y canalizaban ayuda estatal a empresas privadas cuyos proyectos mejorarían el bienestar general: un Sistema Commonwealth. El ingreso promedio per cápita aumentó más del 1 por ciento anual, más del 30 por ciento en una generación.", "cause_es": "El embargo de Jefferson de 1807 cortó los productos y el crédito europeos, empujando a los estados a fundar compañías nacionales: New England otorgó cartas a doscientas compañías y Pennsylvania a más de mil cien.", "sig_es": "El mercantilismo estatal creó una economía política republicana que hizo compatibles la propiedad privada y el intercambio de mercado con un gobierno activista.", "exp_es": "El crecimiento americano temprano se construyó con ayuda pública, no solo con laissez-faire.", "who_es": [], "img": {"file": "img:f1_2680", "credit": "图源：Henretta《America's History》第8版 p.250"}}, {"id": "p3-049", "period": 3, "topic_en": "Panic of 1819", "topic_zh": "1819年恐慌", "year": 1819, "year_text": "1819", "who": [], "who_zh": [], "what_en": "In 1818 farmers and planters faced an abrupt 30 percent drop in world agricultural prices: raw cotton in South Carolina fell from 34 to 15 cents a pound and wheat prices plummeted. Farmers could not pay debts, stores and banks went bankrupt, and land prices dropped by 50 percent.", "what_zh": "1818年农民和种植园主遭遇世界农产品价格骤降三成：南卡罗来纳原棉从每磅34美分跌至15美分，小麦价格暴跌。农民无力还债，商店和银行破产，地价下跌五成。", "cause_en": "As the Napoleonic Wars ended in 1815, Americans over-consumed English goods; then world prices collapsed while Britain closed the West Indies to American trade.", "cause_zh": "1815年拿破仑战争结束，美国人过度消费英国商品；随后世界价格崩盘，英国又关闭西印度群岛对美贸易。", "sig_en": "The panic gave Americans their first taste of a business cycle — the periodic boom and bust inherent to an unregulated market economy — and devastated artisans and farmers selling in national markets.", "sig_zh": "这次恐慌让美国人第一次尝到商业周期的滋味——不受管制市场经济固有的周期性繁荣与萧条——并重创了面向全国市场的手工业者和农民。", "exp_en": "America's first depression taught that markets could collapse as well as expand.", "exp_zh": "美国第一次萧条教会人们：市场会扩张，也会崩溃。", "page": 251, "topic_es": "Pánico de 1819", "what_es": "En 1818, agricultores y plantadores enfrentaron una abrupta caída del 30 por ciento en los precios agrícolas mundiales: el algodón en bruto en South Carolina cayó de 34 a 15 centavos la libra y los precios del trigo se desplomaron. Los agricultores no podían pagar sus deudas, tiendas y bancos quebraron, y los precios de la tierra cayeron un 50 por ciento.", "cause_es": "Cuando las Guerras Napoleónicas terminaron en 1815, los americanos consumieron en exceso productos ingleses; luego los precios mundiales colapsaron mientras Britain cerraba las West Indies al comercio americano.", "sig_es": "El pánico dio a los americanos su primera experiencia de un ciclo económico —el auge y la caída periódicos inherentes a una economía de mercado no regulada— y devastó a artesanos y agricultores que vendían en mercados nacionales.", "exp_es": "La primera depresión de América enseñó que los mercados podían colapsar además de expandirse.", "who_es": [], "img": {"file": "img:f1_2684", "credit": "图源：Henretta《America's History》第8版 p.251"}}, {"id": "p3-050", "period": 3, "topic_en": "Sentimentalism and companionate marriage", "topic_zh": "感伤主义与情投意合的婚姻", "year": null, "year_text": "after 1800", "who": [], "who_zh": [], "what_en": "Sentimentalism originated in Europe as part of the Romantic movement and, after 1800, spread quickly through all classes of American society. Rejecting the Enlightenment's emphasis on rational thought, it celebrated feeling — a physical, sensuous appreciation of God, nature, and fellow humans. Young men and women increasingly chose their own partners in companionate marriages contracted from motives of affection.", "what_zh": "感伤主义源于欧洲浪漫主义运动，1800年后迅速传遍美国各阶层。它摒弃启蒙运动对理性思考的强调，颂扬“情感”——对上帝、自然和同胞的身体的、感性的体悟。年轻人越来越多地自主择偶，缔结出于感情的“情投意合的婚姻”。", "cause_en": "Shrinking landholdings gave yeomen fathers fewer resources to control their children's marriages, and a new cultural attitude elevated emotion over calculation.", "cause_zh": "土地越分越小，自耕农父亲控制子女婚姻的资源减少；新的文化风尚把情感置于算计之上。", "sig_en": "Sentimentalism reshaped family life, literature, popular melodrama, and even revivalist preaching, marking a cultural break from Enlightenment rationalism.", "sig_zh": "感伤主义重塑了家庭生活、文学、通俗情节剧乃至复兴派布道，标志着与启蒙理性主义的文化决裂。", "why_term": "sentimentalism", "why_term_q": "1800年后流行、强调情感而非理性的文化思潮是 ______。", "exp_en": "Feeling replaced reason as the era's cultural ideal, even in choosing a spouse.", "exp_zh": "情感取代理性成为时代的文化理想，连择偶也不例外。", "page": 258, "topic_es": "Sentimentalismo y matrimonio por compañerismo", "what_es": "El sentimentalismo se originó en Europa como parte del movimiento romántico y, después de 1800, se extendió rápidamente por todas las clases de la sociedad americana. Rechazando el énfasis de la Ilustración en el pensamiento racional, celebraba el sentimiento: una apreciación física y sensual de Dios, la naturaleza y los semejantes. Los jóvenes elegían cada vez más a sus propias parejas en matrimonios por compañerismo contraídos por motivos de afecto.", "cause_es": "La reducción de las tierras dio a los padres yeomen menos recursos para controlar los matrimonios de sus hijos, y una nueva actitud cultural elevó la emoción sobre el cálculo.", "sig_es": "El sentimentalismo remodeló la vida familiar, la literatura, el melodrama popular e incluso la predicación revivalista, marcando una ruptura cultural con el racionalismo de la Ilustración.", "exp_es": "El sentimiento reemplazó a la razón como ideal cultural de la era, incluso al elegir cónyuge.", "why_term_q_es": "El movimiento cultural que después de 1800 enfatizó el sentimiento sobre la razón es ______.", "who_es": []}, {"id": "p3-051", "period": 3, "topic_en": "Republican motherhood", "topic_zh": "共和母亲", "year": null, "year_text": "1780s-1790s", "who": ["Benjamin Rush", "Thomas Bernard"], "who_zh": ["本杰明·拉什", "托马斯·伯纳德"], "what_en": "As women bore fewer children but took greater responsibility for the family, Americans called for loyal republican mothers who would instruct their sons in the principles of liberty and government. The Reverend Thomas Bernard told the Female Charitable Society of Salem that preserving virtue and instructing the young were the real Rights of Women — not voting or serving on juries.", "what_zh": "随着妇女少生孩子但承担更多家庭责任，美国人呼吁忠诚的“共和母亲”把自由与政府的原则教给儿子。托马斯·伯纳德牧师对塞勒姆妇女慈善协会说，守护美德、教育子女才是妇女真正的权利——而非投票或担任陪审员。", "cause_en": "The demographic transition and republican ideology gave mothers a new civic mission: raising virtuous republican citizens.", "cause_zh": "人口转型和共和意识形态赋予母亲新的公民使命：培养有美德的共和公民。", "sig_en": "Republican motherhood justified better female education while keeping women out of formal politics — a bargain that shaped women's public roles for decades.", "sig_zh": "“共和母亲”论为妇女争取到更好的教育，却把她们挡在正式政治之外——这一交易塑造了此后数十年妇女的公共角色。", "exp_en": "Women gained influence as mothers precisely by renouncing political rights.", "exp_zh": "妇女恰恰通过放弃政治权利，换来了作为母亲的影响力。", "page": 259, "src": {"text": "Preserving virtue and instructing the young are not the fancied, but the real Rights of Women", "attr": "Reverend Thomas Bernard"}, "topic_es": "Maternidad republicana", "what_es": "A medida que las mujeres tenían menos hijos pero asumían mayor responsabilidad por la familia, los americanos pidieron madres republicanas leales que instruyeran a sus hijos en los principios de la libertad y el gobierno. El reverendo Thomas Bernard dijo a la Sociedad Caritativa Femenina de Salem que preservar la virtud e instruir a los jóvenes eran los verdaderos Derechos de la Mujer, no votar ni servir en jurados.", "cause_es": "La transición demográfica y la ideología republicana dieron a las madres una nueva misión cívica: criar ciudadanos republicanos virtuosos.", "sig_es": "La maternidad republicana justificó una mejor educación femenina mientras mantenía a las mujeres fuera de la política formal: un pacto que moldeó los roles públicos de las mujeres durante décadas.", "exp_es": "Las mujeres ganaron influencia como madres precisamente al renunciar a los derechos políticos.", "who_es": ["Benjamin Rush", "Thomas Bernard"], "img": {"file": "img:f1_2705", "credit": "图源：Henretta《America's History》第8版 p.259"}}, {"id": "p3-052", "period": 3, "topic_en": "Demographic transition", "topic_zh": "人口转型", "year": null, "year_text": "from the 1790s", "who": [], "who_zh": [], "what_en": "Beginning in the 1790s the United States was among the first nations to experience a sharp decline in the birthrate — what historians call the demographic transition. In Sturbridge, Massachusetts, women bore an average of six children while their grandmothers had eight or nine; in seaport cities native-born white women averaged only four.", "what_zh": "从1790年代起，美国成为最早经历出生率锐减的国家之一——史学家称之为“人口转型”。马萨诸塞州斯特布里奇妇女平均生育六个孩子，而她们的祖母辈是八九个；海港城市本土白人妇女平均只生四个。", "cause_en": "Young men migrated west, delaying marriage; urban middle-class couples deliberately limited family size to leave adequate inheritances, using birth control or abstinence.", "cause_zh": "年轻人西迁推迟了结婚年龄；城市中产夫妇为给子女留足遗产而主动限制家庭规模，采用避孕或禁欲。", "sig_en": "Smaller families changed women's lives, freeing mothers from lifelong childbearing and feeding the ideal of republican motherhood.", "sig_zh": "小家庭改变了妇女的生活，使母亲摆脱终身生育，也助长了“共和母亲”的理想。", "exp_en": "Americans began choosing smaller families a century before the rest of the West.", "exp_zh": "美国人比西方其他国家早一个世纪开始选择小家庭。", "page": 259, "topic_es": "Transición demográfica", "what_es": "A partir de la década de 1790, Estados Unidos estuvo entre las primeras naciones en experimentar una fuerte caída en la tasa de natalidad, lo que los historiadores llaman la transición demográfica. En Sturbridge, Massachusetts, las mujeres tenían un promedio de seis hijos mientras sus abuelas habían tenido ocho o nueve; en las ciudades portuarias, las mujeres blancas nativas promediaban solo cuatro.", "cause_es": "Los jóvenes migraban al oeste, retrasando el matrimonio; las parejas urbanas de clase media limitaban deliberadamente el tamaño de la familia para dejar herencias adecuadas, usando control de natalidad o abstinencia.", "sig_es": "Las familias más pequeñas cambiaron la vida de las mujeres, liberando a las madres de una maternidad de por vida y alimentando el ideal de la maternidad republicana.", "exp_es": "Los americanos comenzaron a elegir familias más pequeñas un siglo antes que el resto de Occidente.", "who_es": [], "img": {"file": "img:f1_2705", "credit": "图源：Henretta《America's History》第8版 p.259"}}, {"id": "p3-053", "period": 3, "topic_en": "Manumission and gradual emancipation", "topic_zh": "释奴与渐进废奴", "year": 1782, "year_text": "1782", "who": ["John Woolman"], "who_zh": ["约翰·伍尔曼"], "what_en": "Following Virginia's manumission act of 1782, allowing owners to free their slaves, 10,000 slaves won their freedom. Quaker evangelist John Woolman had urged Friends to free their slaves since the 1750s, and in 1784 a conference of Virginia Methodists declared slavery contrary to the Golden Law of God.", "what_zh": "弗吉尼亚1782年通过释奴法、允许奴主解放奴隶后，1万名奴隶获得自由。贵格派布道家约翰·伍尔曼自1750年代起就敦促教友释奴；1784年弗吉尼亚卫理公会会议宣布奴隶制违背上帝的“金律”。", "cause_en": "Revolutionary ideals of liberty, evangelical religion, and Enlightenment philosophy challenging belief in African inferiority all encouraged manumission.", "cause_zh": "革命的自由理想、福音派宗教，以及挑战黑人低劣论的启蒙哲学，共同推动了释奴。", "sig_en": "Thousands of African Americans won freedom and thousands more supported the Patriot cause, though emancipation stalled in the South after 1800.", "sig_zh": "数千非裔美国人获得自由，更多人支持爱国者事业，尽管南方废奴在1800年后停滞。", "exp_en": "The Revolution's liberty talk briefly cracked slavery's hold in the Upper South.", "exp_zh": "革命的自由话语曾短暂撼动上南方的奴隶制。", "page": 265, "topic_es": "Manumisión y emancipación gradual", "what_es": "Tras la ley de manumisión de Virginia de 1782, que permitía a los propietarios liberar a sus esclavos, 10.000 esclavos ganaron su libertad. El evangelista cuáquero John Woolman había instado a los Amigos a liberar a sus esclavos desde la década de 1750, y en 1784 una conferencia de metodistas de Virginia declaró la esclavitud contraria a la Ley Dorada de Dios.", "cause_es": "Los ideales revolucionarios de libertad, la religión evangélica y la filosofía de la Ilustración que desafiaba la creencia en la inferioridad africana alentaron la manumisión.", "sig_es": "Miles de afroamericanos ganaron la libertad y miles más apoyaron la causa patriota, aunque la emancipación se estancó en el Sur después de 1800.", "exp_es": "El discurso de libertad de la Revolución resquebrajó brevemente el control de la esclavitud en el Alto Sur.", "who_es": ["John Woolman"], "img": {"file": "img:f1_2726", "credit": "图源：Henretta《America's History》第8版 p.265"}}, {"id": "p3-054", "period": 3, "topic_en": "Herrenvolk republic", "topic_zh": "主人种族共和国", "year": null, "year_text": "after 1800", "who": ["Gabriel Prosser"], "who_zh": ["加布里埃尔·普罗瑟"], "what_en": "After Virginia authorities thwarted Gabriel Prosser's planned uprising in 1800 and hanged him and thirty followers, southern leaders redefined republicanism: they restricted individual liberty and legal equality to whites, creating what historians call a herrenvolk (master race) republic. South Carolina and Georgia also reopened the Atlantic slave trade, importing about 115,000 Africans between 1790 and 1808.", "what_zh": "1800年弗吉尼亚当局挫败加布里埃尔·普罗瑟策划的起义并绞死他及三十名追随者后，南方领袖重新定义共和主义：把个人自由和法律平等限定于白人，形成史学家所说的“主人种族”（herrenvolk）共和国。南卡罗来纳和佐治亚还重开大西洋奴隶贸易，1790至1808年间输入约11.5万非洲人。", "cause_en": "Fear of slave revolt, spread by the Haitian Revolution and Prosser's conspiracy, convinced southern whites that liberty for blacks meant danger for themselves.", "cause_zh": "海地革命和普罗瑟阴谋引发的对奴隶起义的恐惧，使南方白人相信黑人的自由就是自己的危险。", "sig_en": "Debate over emancipation ended in the South; republican equality became a whites-only privilege, deepening the sectional divide.", "sig_zh": "南方关于废奴的辩论终结；共和平等变成白人专属特权，南北分歧加深。", "why_term": "herrenvolk republic", "why_term_q": "南方把自由平等限定于白人的政体概念（关键词）是 ______。", "exp_en": "The South answered the fear of rebellion by making republicanism racial.", "exp_zh": "南方用种族化的共和主义回应了对起义的恐惧。", "page": 266, "topic_es": "República herrenvolk", "what_es": "Después de que las autoridades de Virginia frustraran la planeada sublevación de Gabriel Prosser en 1800 y lo ahorcaran a él y a treinta seguidores, los líderes sureños redefinieron el republicanismo: restringieron la libertad individual y la igualdad legal a los blancos, creando lo que los historiadores llaman una república herrenvolk (raza de amos). South Carolina y Georgia también reabrieron el comercio atlántico de esclavos, importando unos 115.000 africanos entre 1790 y 1808.", "cause_es": "El miedo a la revuelta de esclavos, propagado por la Revolución Haitiana y la conspiración de Prosser, convenció a los blancos sureños de que la libertad para los negros significaba peligro para ellos.", "sig_es": "El debate sobre la emancipación terminó en el Sur; la igualdad republicana se convirtió en un privilegio solo para blancos, profundizando la división seccional.", "exp_es": "El Sur respondió al miedo a la rebelión haciendo racial al republicanismo.", "why_term_q_es": "El concepto sureño de una república que limitaba la libertad y la igualdad a los blancos (palabra clave) es ______.", "who_es": ["Gabriel Prosser"]}, {"id": "p3-055", "period": 3, "topic_en": "American Colonization Society", "topic_zh": "美国殖民协会", "year": 1817, "year_text": "1817", "who": ["Henry Clay"], "who_zh": ["亨利·克莱"], "what_en": "In 1817 a group of prominent citizens founded the American Colonization Society. Henry Clay and other colonizationists argued that slaves had to be freed and then resettled in Africa or elsewhere — emancipation without removal would lead to chaos. The society resettled only about 6,000 African Americans in Liberia, its colony on the west coast of Africa.", "what_zh": "1817年一批名流创办美国殖民协会。亨利·克莱等殖民主义者主张奴隶必须先解放、再迁往非洲或其他地方——不迁走的解放将导致混乱。该协会只把约6000名非裔美国人安置到其在西非的殖民地利比里亚。", "cause_en": "The cotton boom made planters unwilling to free slaves, while racial fears made whites unwilling to live alongside free blacks.", "cause_zh": "棉花繁荣使种植园主不愿释奴，种族恐惧又使白人不愿与自由黑人共处。", "sig_en": "Most free blacks strongly opposed colonization, seeing themselves as Americans; the scheme's failure showed that gradual, removal-based emancipation was a dead end.", "sig_zh": "多数自由黑人强烈反对殖民方案，自视为美国人；该计划的失败表明，渐进式迁走型废奴是死胡同。", "exp_en": "Colonization promised to end slavery by removing black people; almost no one it targeted wanted to go.", "exp_zh": "殖民方案承诺以迁走黑人来终结奴隶制，但目标人群几乎无人愿走。", "page": 267, "topic_es": "American Colonization Society", "what_es": "En 1817, un grupo de ciudadanos prominentes fundó la American Colonization Society. Henry Clay y otros colonizacionistas argumentaban que los esclavos debían ser liberados y luego reasentados en África o en otro lugar: la emancipación sin traslado llevaría al caos. La sociedad reasentó solo a unos 6.000 afroamericanos en Liberia, su colonia en la costa occidental de África.", "cause_es": "El auge del algodón hizo que los plantadores no quisieran liberar esclavos, mientras los temores raciales hacían que los blancos no quisieran vivir junto a negros libres.", "sig_es": "La mayoría de los negros libres se opuso firmemente a la colonización, viéndose a sí mismos como americanos; el fracaso del plan mostró que la emancipación gradual basada en el traslado era un callejón sin salida.", "exp_es": "La colonización prometía acabar con la esclavitud trasladando a la gente negra; casi ninguno de sus destinatarios quería irse.", "who_es": ["Henry Clay"], "img": {"file": "img:f1_2732", "credit": "图源：Henretta《America's History》第8版 p.267"}}, {"id": "p3-056", "period": 3, "topic_en": "Richard Allen and the black church", "topic_zh": "理查德·艾伦与黑人教会", "year": null, "year_text": "late 1700s", "who": ["Richard Allen"], "who_zh": ["理查德·艾伦"], "what_en": "Born into slavery in Philadelphia in 1760, Richard Allen was converted to Methodism in 1777, allowed to buy his freedom, and became a licensed exhorter and then a regular minister. As Bishop of the African Methodist Episcopal Church he declared: This land which we have watered with our tears and our blood is now our mother country.", "what_zh": "理查德·艾伦1760年生为费城的奴隶，1777年皈依卫理公会，获准赎身，先后成为“持证劝勉员”和正式牧师。作为非洲卫理公会主教，他宣称：“这片我们用泪水和鲜血浇灌的土地，如今就是我们的祖国。”", "cause_en": "Revivals converted thousands of African Americans to Baptists and Methodists, who created their own powerful institution: the black Christian church.", "cause_zh": "复兴运动使数千非裔美国人皈依浸礼会和卫理公会，他们创建了自己的强大机构：黑人基督教会。", "sig_en": "The black church became the central institution of free black life and a base for opposing colonization schemes.", "sig_zh": "黑人教会成为自由黑人生活的中心机构，也是反对殖民方案的阵地。", "exp_en": "Allen's church gave free blacks an institution of their own and a claim on America.", "exp_zh": "艾伦的教会给了自由黑人自己的机构和对美国的主张。", "page": 267, "src": {"text": "this land which we have watered with our tears and our blood is now our mother country", "attr": "Bishop Richard Allen"}, "topic_es": "Richard Allen y la iglesia negra", "what_es": "Nacido en la esclavitud en Philadelphia en 1760, Richard Allen se convirtió al metodismo en 1777, se le permitió comprar su libertad y se convirtió en exhortador licenciado y luego en ministro regular. Como obispo de la African Methodist Episcopal Church declaró: «Esta tierra que hemos regado con nuestras lágrimas y nuestra sangre es ahora nuestra madre patria».", "cause_es": "Los avivamientos convirtieron a miles de afroamericanos al bautismo y al metodismo, quienes crearon su propia poderosa institución: la iglesia cristiana negra.", "sig_es": "La iglesia negra se convirtió en la institución central de la vida negra libre y en una base para oponerse a los planes de colonización.", "exp_es": "La iglesia de Allen dio a los negros libres una institución propia y un reclamo sobre América.", "who_es": ["Richard Allen"], "img": {"file": "img:f1_2732", "credit": "图源：Henretta《America's History》第8版 p.267"}}, {"id": "p3-057", "period": 3, "topic_en": "Missouri Compromise", "topic_zh": "密苏里妥协案", "year": 1820, "year_text": "1820-1821", "who": [], "who_zh": [], "what_en": "The Missouri Compromise resolved for a generation the issue of slavery in the Louisiana Purchase lands: it prohibited slavery north of Missouri's southern border, admitted Maine as a free state in 1820 and Missouri as a slave state in 1821. Jefferson called the crisis a fire-bell in the night that awakened and filled him with terror.", "what_zh": "密苏里妥协案把路易斯安那购地内奴隶制问题搁置了一代人：禁止在密苏里南界以北实行奴隶制，缅因1820年以自由州加入、密苏里1821年以蓄奴州加入。杰斐逊称这场危机是“黑夜中的火警钟”，让他惊醒并充满恐惧。", "cause_en": "Missouri's application for statehood as a slave state threatened the Senate's sectional balance and forced Congress to confront slavery's expansion.", "cause_zh": "密苏里以蓄奴州申请加入联邦，威胁参议院的南北平衡，迫使国会直面奴隶制扩张问题。", "sig_en": "The compromise kept the Union together but revealed slavery as the republic's most dangerous sectional fault line.", "sig_zh": "妥协保住了联邦，却暴露了奴隶制是共和国最危险的南北断层线。", "exp_en": "Missouri bought thirty years of peace by drawing a line slavery could not cross.", "exp_zh": "密苏里妥协用一条奴隶制不得跨越的线，买了三十年和平。", "page": 269, "src": {"text": "This momentous question, like a fire-bell in the night, awakened and filled me with terror.", "attr": "Thomas Jefferson"}, "topic_es": "Missouri Compromise", "what_es": "El Missouri Compromise resolvió por una generación el tema de la esclavitud en las tierras de la Compra de Louisiana: prohibió la esclavitud al norte de la frontera sur de Missouri, admitió a Maine como estado libre en 1820 y a Missouri como estado esclavista en 1821. Jefferson llamó a la crisis una campana de incendio en la noche que lo despertó y lo llenó de terror.", "cause_es": "La solicitud de Missouri de ingresar como estado esclavista amenazó el equilibrio seccional del Senado y obligó al Congreso a enfrentar la expansión de la esclavitud.", "sig_es": "El compromiso mantuvo unida a la Unión pero reveló a la esclavitud como la falla seccional más peligrosa de la república.", "exp_es": "Missouri compró treinta años de paz trazando una línea que la esclavitud no podía cruzar.", "who_es": [], "img": {"file": "img:f1_2738", "credit": "图源：Henretta《America's History》第8版 p.269"}}, {"id": "p3-058", "period": 3, "topic_en": "Disestablishment and voluntarism", "topic_zh": "政教分离与自愿主义", "year": null, "year_text": "after independence", "who": ["Thomas Jefferson", "Isaac Backus"], "who_zh": ["托马斯·杰斐逊", "艾萨克·巴克斯"], "what_en": "After independence, Americans dismantled established churches and embraced voluntarism — the funding of churches by their members. Jefferson declared that religion lies solely between man and his God; Baptists like Isaac Backus warned against incorporating churches or accepting public funds lest it lead to state control.", "what_zh": "独立后美国人拆除了官方教会，奉行“自愿主义”——教会由信徒出资维持。杰斐逊宣称宗教纯属个人与上帝之间的事；巴克斯等浸礼会信徒警告不要让教会法人化或接受公款，以免招致国家控制。", "cause_en": "Enlightenment deism and evangelical Protestantism alike condemned religious restrictions and demanded complete freedom of conscience.", "cause_zh": "启蒙自然神论和福音派新教都谴责宗教限制，要求完全的信仰自由。", "sig_en": "Disestablishment let Americans choose republican church institutions — spiritually equal, democratically self-governed — and made faith a voluntary, competitive enterprise.", "sig_zh": "政教分离让美国人选择共和式教会——灵性平等、民主自治——使信仰成为自愿的、竞争性的事业。", "exp_en": "Separating church and state unleashed the religious energies of the Second Great Awakening.", "exp_zh": "政教分离释放了第二次大觉醒的宗教能量。", "page": 270, "topic_es": "Desestablecimiento y voluntarismo", "what_es": "Después de la independencia, los americanos desmantelaron las iglesias establecidas y abrazaron el voluntarismo: la financiación de las iglesias por sus miembros. Jefferson declaró que la religión yace únicamente entre el hombre y su Dios; bautistas como Isaac Backus advirtieron contra incorporar iglesias o aceptar fondos públicos por temor a que llevara al control estatal.", "cause_es": "El deísmo de la Ilustración y el protestantismo evangélico condenaron por igual las restricciones religiosas y exigieron completa libertad de conciencia.", "sig_es": "El desestablecimiento permitió a los americanos elegir instituciones eclesiásticas republicanas —espiritualmente iguales, democráticamente autogobernadas— e hizo de la fe una empresa voluntaria y competitiva.", "exp_es": "Separar la iglesia del estado desató las energías religiosas del Segundo Gran Despertar.", "who_es": ["Thomas Jefferson", "Isaac Backus"]}, {"id": "p3-059", "period": 3, "topic_en": "Second Great Awakening", "topic_zh": "第二次大觉醒", "year": null, "year_text": "1790s-1800s", "who": [], "who_zh": [], "what_en": "Evangelical denominations began a decades-long series of revivals — the Second Great Awakening — in the 1790s, spreading through seacoast cities and the New England backcountry. After 1800 camp meetings swept the frontier; the largest, at Cane Ridge, Kentucky, in 1801, lasted nine electrifying days and nights and attracted almost 20,000 people. Baptist and Methodist preachers reshaped American religion.", "what_zh": "1790年代福音派教派开启了长达数十年的复兴系列——第二次大觉醒，席卷海滨城市和新英格兰内陆。1800年后野营聚会席卷边疆；规模最大的是1801年肯塔基州凯恩里奇聚会，持续九个激动人心的昼夜，吸引近2万人。浸礼会和卫理公会传道人重塑了美国宗教。", "cause_en": "Disestablishment created a competitive religious marketplace, and frontier settlers hungered for an emotional, egalitarian faith.", "cause_zh": "政教分离造就了竞争性的宗教市场，边疆移民渴望情感化、平等主义的信仰。", "sig_en": "The revivals made the United States a genuinely Christian society, gave new public roles to white women and blacks, and set in motion long-lasting movements for social reform.", "sig_zh": "复兴运动使美国成为真正的基督教社会，给白人妇女和黑人带来新的公共角色，并启动了持久的社会改革运动。", "exp_en": "Revivalism democratized American religion and mobilized it for reform.", "exp_zh": "复兴主义使美国宗教民主化，并将其动员起来投身改革。", "page": 271, "topic_es": "Segundo Gran Despertar", "what_es": "Las denominaciones evangélicas comenzaron una serie de avivamientos de décadas —el Segundo Gran Despertar— en la década de 1790, extendiéndose por las ciudades costeras y el interior de New England. Después de 1800, las reuniones campestres barrieron la frontera; la más grande, en Cane Ridge, Kentucky, en 1801, duró nueve electrizantes días y noches y atrajo a casi 20.000 personas. Los predicadores bautistas y metodistas remodelaron la religión americana.", "cause_es": "El desestablecimiento creó un mercado religioso competitivo, y los colonos de la frontera anhelaban una fe emocional e igualitaria.", "sig_es": "Los avivamientos hicieron de Estados Unidos una sociedad genuinamente cristiana, dieron nuevos roles públicos a las mujeres blancas y a los negros, y pusieron en marcha duraderos movimientos de reforma social.", "exp_es": "El revivalismo democratizó la religión americana y la movilizó para la reforma.", "who_es": []}, {"id": "p3-060", "period": 3, "topic_en": "Emma Willard and women's education", "topic_zh": "艾玛·威拉德与女子教育", "year": 1814, "year_text": "1814", "who": ["Emma Willard"], "who_zh": ["艾玛·威拉德"], "what_en": "Emma Willard, the first American advocate of higher education for women, opened the Middlebury Female Seminary in Vermont in 1814 and later founded girls' academies in Waterford and Troy, New York. Beginning in the 1820s, women educated in these seminaries displaced men as public-school teachers, earning 12 to 14 dollars a month with room and board.", "what_zh": "艾玛·威拉德是美国女子高等教育的第一位倡导者，1814年在佛蒙特州创办米德尔伯里女子神学院，后又在纽约州沃特福德和特洛伊创办女子学院。从1820年代起，这些学校培养的女性取代男性成为公立学校教师，月薪12至14美元（含食宿）。", "cause_en": "Churches sponsored academies where middling-class girls received intellectual and moral instruction, and republican motherhood demanded educated mothers.", "cause_zh": "教会资助学院为中产女孩提供知德教育，“共和母亲”理念也需要有文化的母亲。", "sig_en": "Teaching gave women an acknowledged place in public life, a status previously beyond their reach, even though they accepted lower pay than men.", "sig_zh": "教书使妇女在公共生活中获得公认的一席之地——这是以前可望不可即的地位，尽管她们接受比男性低的薪水。", "exp_en": "Female seminaries turned educated daughters into the nation's schoolteachers.", "exp_zh": "女子学院把受过教育的女儿们变成了国家的教师队伍。", "page": 276, "topic_es": "Emma Willard y la educación de las mujeres", "what_es": "Emma Willard, la primera defensora americana de la educación superior para las mujeres, abrió el Seminario Femenino de Middlebury en Vermont en 1814 y luego fundó academias para niñas en Waterford y Troy, New York. A partir de la década de 1820, las mujeres educadas en estos seminarios desplazaron a los hombres como maestras de escuelas públicas, ganando de 12 a 14 dólares al mes con alojamiento y comida.", "cause_es": "Las iglesias patrocinaban academias donde las niñas de clase media recibían instrucción intelectual y moral, y la maternidad republicana exigía madres educadas.", "sig_es": "La enseñanza dio a las mujeres un lugar reconocido en la vida pública, un estatus previamente fuera de su alcance, aunque aceptaban un salario menor que los hombres.", "exp_es": "Los seminarios femeninos convirtieron a las hijas educadas en las maestras de la nación.", "who_es": ["Emma Willard"]}];